INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_2_kor_u4_L01_basic#1','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',1,'mc','auto','「고유어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X19']::text[],false,'{"seq":1,"concept":"K6-2-u4-C1","difficulty":1,"kind":"mc","stem":"「고유어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리말에 처음부터 있던 낱말이나 그것을 바탕으로 만들어진 낱말","correct":true},{"t":"한자로 이루어진 낱말","mis":"K6-2-u4-X01"},{"t":"다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말","mis":"K6-2-u4-X01"},{"t":"어느 고장에서만 주로 쓰는 낱말","mis":"K6-2-u4-X19"}],"explanation":["한자로 이루어진 낱말은 한자어예요.","다른 나라에서 들어온 낱말은 외래어예요.","처음부터 있던 말과 그것으로 만든 말이 고유어예요."]}'::jsonb),
('g6_2_kor_u4_L01_basic#2','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',1,'sa','auto','다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C1","difficulty":1,"kind":"sa","stem":"다른 나라에서 들어와 우리 생활에서 널리 쓰이는 낱말을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["외래어"],"explanation":["고유어는 처음부터 있던 말이에요.","한자어는 한자로 된 말이에요.","다른 나라에서 들어와 널리 쓰이면 외래어예요."],"mis":"K6-2-u4-X01"}'::jsonb),
('g6_2_kor_u4_L01_basic#3','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',1,'ox','auto','우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이에요.',ARRAY['K6-2-u4-X02']::text[],false,'{"seq":3,"concept":"K6-2-u4-C2","difficulty":1,"kind":"ox","stem":"우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이에요.","answer":"X","reason_options":[{"t":"듣는 사람이 알아들을 수 있게, 뜻에 맞게 쓰는 것이기 때문에","correct":true},{"t":"한자어와 외래어는 우리말을 해치기 때문에","mis":"K6-2-u4-X02"}],"mis":"K6-2-u4-X02","explanation":["우리말에는 세 갈래가 모두 들어 있어요.","바르게 쓰기는 알아들을 수 있게, 뜻에 맞게 쓰는 것이에요.","다른 갈래를 몰아내는 것이 아니에요."]}'::jsonb),
('g6_2_kor_u4_L01_basic#4','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C3',1,'mc','auto','지나치게 줄인 말을 쓰면 어떤 일이 생길 수 있나요?',ARRAY['K6-2-u4-X03','K6-2-u4-X04']::text[],false,'{"seq":4,"concept":"K6-2-u4-C3","difficulty":1,"kind":"mc","stem":"지나치게 줄인 말을 쓰면 어떤 일이 생길 수 있나요?","options":[{"t":"아는 사람끼리만 통해서 옆 사람이 알아듣지 못한다","correct":true},{"t":"누구나 더 빨리 알아듣는다","mis":"K6-2-u4-X03"},{"t":"낱말의 뜻이 저절로 바뀐다","mis":"K6-2-u4-X04"},{"t":"아무 일도 생기지 않는다","mis":"K6-2-u4-X04"}],"explanation":["줄인 말은 짧아서 편해 보여요.","그러나 아는 사람끼리만 통해요.","함께 있는 사람이 대화에서 밀려나요."]}'::jsonb),
('g6_2_kor_u4_L01_basic#5','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',2,'mc','auto','할머니가 말한 「해거름」은 어떤 때를 가리키나요?',ARRAY['K6-2-u4-X18']::text[],false,'{"seq":5,"concept":"K6-2-u4-C1","difficulty":2,"kind":"mc","stem":"할머니가 말한 「해거름」은 어떤 때를 가리키나요?","options":[{"t":"해가 서쪽으로 넘어갈 무렵","correct":true},{"t":"해가 막 떠오르는 이른 아침","mis":"K6-2-u4-X18"},{"t":"해가 지고 한참 지난 깊은 밤","mis":"K6-2-u4-X18"},{"t":"해가 하늘 한가운데 있는 낮","mis":"K6-2-u4-X18"}],"explanation":["할머니가 「산 너머로 넘어가려고 붉어질 때」라고 다시 말해 주었어요.","해솔이도 「저녁이 되기 조금 전」이라고 짐작했어요.","앞뒤 말을 살피면 처음 듣는 낱말도 뜻을 짐작할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"해솔아, 해거름 전에 텃밭 좀 둘러보고 오렴."},{"who":"해솔","text":"네? 해거름이요? 그게 언제인데요?"},{"who":"할머니","text":"저 해가 산 너머로 넘어가려고 붉어질 때 있잖니. 그때 말이다."},{"who":"해솔","text":"아, 저녁이 되기 조금 전이요? 처음 들어 본 말이에요."}]}}'::jsonb),
('g6_2_kor_u4_L01_basic#6','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',2,'match','auto','낱말과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C1","difficulty":2,"kind":"match","stem":"낱말과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"나들이","r":"고유어"},{"l":"체육","r":"한자어"},{"l":"버튼","r":"외래어"}],"mis":"K6-2-u4-X01","explanation":["나들이는 처음부터 있던 우리말이에요.","체육은 한자로 된 말이에요.","버튼은 다른 나라에서 들어와 널리 쓰이는 말이에요."]}'::jsonb),
('g6_2_kor_u4_L01_basic#7','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',2,'mc','auto','우리말을 바르게 사용하는 사람의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X03','K6-2-u4-X19']::text[],false,'{"seq":7,"concept":"K6-2-u4-C2","difficulty":2,"kind":"mc","stem":"우리말을 바르게 사용하는 사람의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람이 알아들을 수 있는 말로 뜻에 맞게 쓴다","correct":true},{"t":"한자어와 외래어는 하나도 쓰지 않는다","mis":"K6-2-u4-X02"},{"t":"어려운 말을 많이 써서 많이 아는 것처럼 보인다","mis":"K6-2-u4-X03"},{"t":"고장의 말을 쓰는 친구를 틀렸다고 고쳐 준다","mis":"K6-2-u4-X19"}],"explanation":["말은 뜻을 주고받으려고 써요.","알아들을 수 있게, 뜻에 맞게 쓰는 것이 바르게 쓰는 거예요.","다른 갈래나 고장 말을 몰아내는 것이 아니에요."]}'::jsonb),
('g6_2_kor_u4_L01_basic#8','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C3',2,'mc','auto','기분을 상하게 하는 말이 문제가 되는 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X04']::text[],false,'{"seq":8,"concept":"K6-2-u4-C3","difficulty":2,"kind":"mc","stem":"기분을 상하게 하는 말이 문제가 되는 까닭은 어느 것인가요?","options":[{"t":"뜻은 통해도 듣는 사람의 마음이 다치기 때문에","correct":true},{"t":"뜻이 통하니 아무 문제가 없기 때문에","mis":"K6-2-u4-X04"},{"t":"아는 사람끼리만 통하기 때문에","mis":"K6-2-u4-X04"},{"t":"국어사전에 실려 있지 않기 때문에","mis":"K6-2-u4-X04"}],"explanation":["기분을 상하게 하는 말은 뜻은 잘 통해요.","그래도 듣는 사람의 마음이 다쳐요.","아는 사람끼리만 통하는 것은 줄인 말의 문제예요."]}'::jsonb),
('g6_2_kor_u4_L01_basic#9','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C1',2,'ox','auto','「체육」은 고유어예요.',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":9,"concept":"K6-2-u4-C1","difficulty":2,"kind":"ox","stem":"「체육」은 고유어예요.","answer":"X","reason_options":[{"t":"한자로 이루어진 한자어이기 때문에","correct":true},{"t":"우리가 날마다 쓰는 말이기 때문에","mis":"K6-2-u4-X01"}],"mis":"K6-2-u4-X01","explanation":["날마다 쓴다고 고유어가 되는 것은 아니에요.","체육은 한자로 이루어진 말이에요.","그래서 한자어예요."]}'::jsonb),
('g6_2_kor_u4_L01_basic#10','kor',6,2,'u4','L01','g6_2_kor_u4_L01_basic','lesson_basic','K6-2-u4-C2',3,'error','auto','이 단원의 약속에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X02']::text[],false,'{"seq":10,"concept":"K6-2-u4-C2","difficulty":3,"kind":"error","stem":"이 단원의 약속에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「고유어를 쓰는 사람이 우리말을 더 잘 쓰는 사람이야.」","correct":true,"mis_target":"K6-2-u4-X07"},{"t":"서하 — 「바꿀 수 있는 말은 쉬운 우리말로 바꾸어 쓰면 좋아.」","mis":"K6-2-u4-X02"},{"t":"윤아 — 「우리말에는 고유어 · 한자어 · 외래어가 모두 들어 있어.」","mis":"K6-2-u4-X02"}],"explanation":["서하와 윤아는 약속을 바르게 말했어요.","도윤은 갈래에 등수를 매겼어요.","고유어를 쓴 사람이 더 낫다고 여기는 것은 약속과 달라요."]}'::jsonb),
('g6_2_kor_u4_L01_challenge#1','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',2,'mc','auto','「굳이 어렵게 쓴 외국어」에 해당하는 것은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X19','K6-2-u4-X01']::text[],false,'{"seq":1,"concept":"K6-2-u4-C3","difficulty":2,"kind":"mc","stem":"「굳이 어렵게 쓴 외국어」에 해당하는 것은 어느 것인가요?","options":[{"t":"쉬운 우리말이 있는데도 외국어를 그대로 쓴 말","correct":true},{"t":"바꿀 말이 마땅히 없어 널리 쓰는 외래어","mis":"K6-2-u4-X08"},{"t":"어느 고장에서 주로 쓰는 말","mis":"K6-2-u4-X19"},{"t":"오래전부터 쓰던 고유어","mis":"K6-2-u4-X01"}],"explanation":["버스처럼 바꿀 말이 없는 외래어는 그대로 써요.","문제는 쉬운 우리말이 있는데도 어렵게 쓴 말이에요.","그러면 알아듣기 어려워져요."]}'::jsonb),
('g6_2_kor_u4_L01_challenge#2','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C11',2,'sa','auto','우리말을 마음껏 쓰지 못하던 때, 흩어진 낱말을 모아 우리말 무엇을 만들려고 애쓴 사람들이 있었나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C11","difficulty":2,"kind":"sa","stem":"우리말을 마음껏 쓰지 못하던 때, 흩어진 낱말을 모아 우리말 무엇을 만들려고 애쓴 사람들이 있었나요? 두 글자로 쓰세요.","answer":["사전"],"explanation":["온 나라에서 쓰이는 낱말을 모아 적었어요.","고장마다 다른 말도 함께 모았어요.","그 기록이 오늘 국어사전의 바탕이 되었어요."],"mis":"K6-2-u4-X15"}'::jsonb),
('g6_2_kor_u4_L01_challenge#3','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',3,'mc','auto','해솔이와 할머니의 대화에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X19','K6-2-u4-X03','K6-2-u4-X06']::text[],false,'{"seq":3,"concept":"K6-2-u4-C2","difficulty":3,"kind":"mc","stem":"해솔이와 할머니의 대화에서 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"처음 듣는 고유어도 앞뒤 말로 뜻을 짐작할 수 있다","correct":true},{"t":"「해거름」은 틀린 말이라 쓰면 안 된다","mis":"K6-2-u4-X19"},{"t":"할머니는 일부러 어려운 말을 골라 썼다","mis":"K6-2-u4-X03"},{"t":"고유어는 옛날 사람만 쓰는 말이다","mis":"K6-2-u4-X06"}],"explanation":["할머니가 다시 풀어 말해 주었어요.","해솔이는 앞뒤 말로 뜻을 짐작했어요.","해거름은 지금도 쓰는 우리말이에요."],"asset":{"type":"speech","turns":[{"who":"할머니","text":"해솔아, 해거름 전에 텃밭 좀 둘러보고 오렴."},{"who":"해솔","text":"네? 해거름이요? 그게 언제인데요?"},{"who":"할머니","text":"저 해가 산 너머로 넘어가려고 붉어질 때 있잖니. 그때 말이다."},{"who":"해솔","text":"아, 저녁이 되기 조금 전이요? 처음 들어 본 말이에요."}]}}'::jsonb),
('g6_2_kor_u4_L01_challenge#4','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',3,'mc','auto','새로 전학 온 친구가 우리 반 아이들끼리 쓰는 줄인 말을 못 알아들어 대화에 끼지 못했어요. 무엇이 문제인가요?',ARRAY['K6-2-u4-X03','K6-2-u4-X04']::text[],false,'{"seq":4,"concept":"K6-2-u4-C3","difficulty":3,"kind":"mc","stem":"새로 전학 온 친구가 우리 반 아이들끼리 쓰는 줄인 말을 못 알아들어 대화에 끼지 못했어요. 무엇이 문제인가요?","options":[{"t":"아는 사람끼리만 통하는 말을 써서 함께 있는 사람이 대화에서 밀려났다","correct":true},{"t":"전학 온 친구가 우리말을 잘 몰라서","mis":"K6-2-u4-X03"},{"t":"줄인 말은 사전에 없어 모두 틀린 말이라서","mis":"K6-2-u4-X04"},{"t":"대화하는 목소리가 작아서","mis":"K6-2-u4-X04"}],"explanation":["문제는 친구가 아니라 말에 있어요.","줄인 말은 아는 사람끼리만 통해요.","그래서 함께 있는 사람이 밀려나요."]}'::jsonb),
('g6_2_kor_u4_L01_challenge#5','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C11',3,'ox','auto','우리말 사전을 만들려던 사람들은 서울에서 쓰는 말만 모았어요.',ARRAY['K6-2-u4-X19']::text[],false,'{"seq":5,"concept":"K6-2-u4-C11","difficulty":3,"kind":"ox","stem":"우리말 사전을 만들려던 사람들은 서울에서 쓰는 말만 모았어요.","answer":"X","reason_options":[{"t":"고장마다 다르게 쓰는 말도 함께 모았기 때문에","correct":true},{"t":"서울 말만 바른 우리말이기 때문에","mis":"K6-2-u4-X19"}],"mis":"K6-2-u4-X19","explanation":["서울에서 쓰는 말만 모으지 않았어요.","고장마다 다르게 쓰는 말도 모았어요.","고장 말도 소중한 우리말이에요."]}'::jsonb),
('g6_2_kor_u4_L01_challenge#6','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',3,'match','auto','말이 잘 통하지 않는 경우와 생기는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C3","difficulty":3,"kind":"match","stem":"말이 잘 통하지 않는 경우와 생기는 일을 알맞게 이으세요.","pairs":[{"l":"지나치게 줄인 말","r":"아는 사람끼리만 통한다"},{"l":"뜻을 알기 어려운 새말","r":"뜻이 서로 다르게 통한다"},{"l":"기분을 상하게 하는 말","r":"뜻은 통해도 마음이 다친다"},{"l":"굳이 어렵게 쓴 외국어","r":"쉬운 말을 두고 알아듣기 어려워진다"}],"mis":"K6-2-u4-X04","explanation":["줄인 말은 끼리끼리만 통해요.","새말은 금방 생겼다 사라져 뜻이 엇갈려요.","기분 상하는 말은 마음을, 어려운 외국어는 알아듣기를 막아요."]}'::jsonb),
('g6_2_kor_u4_L01_challenge#7','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C1',3,'error','auto','낱말의 갈래를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X05']::text[],false,'{"seq":7,"concept":"K6-2-u4-C1","difficulty":3,"kind":"error","stem":"낱말의 갈래를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「‘버스’는 우리가 날마다 타니까 고유어야.」","correct":true,"mis_target":"K6-2-u4-X01"},{"t":"이안 — 「‘나들이’는 사전에 한글 표기만 있으니 고유어야.」","mis":"K6-2-u4-X05"},{"t":"채윤 — 「‘체육’은 사전에 한자가 함께 있으니 한자어야.」","mis":"K6-2-u4-X05"}],"explanation":["이안과 채윤은 사전 표시로 갈래를 가렸어요.","하율은 자주 쓴다는 까닭으로 갈래를 정했어요.","버스는 다른 나라에서 들어온 외래어예요."]}'::jsonb),
('g6_2_kor_u4_L01_challenge#8','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',4,'mc','auto','이 단원의 약속에 가장 가깝게 말한 것은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X02','K6-2-u4-X03']::text[],false,'{"seq":8,"concept":"K6-2-u4-C2","difficulty":4,"kind":"mc","stem":"이 단원의 약속에 가장 가깝게 말한 것은 어느 것인가요?","options":[{"t":"「‘다운로드’는 ‘내려받기’로 바꾸어도 잘 통하니 바꾸어 쓰고, ‘버스’처럼 바꿀 말이 마땅치 않은 말은 그대로 쓰자.」","correct":true},{"t":"「‘버스’도 고유어로 바꾸어야 우리말을 지킬 수 있어.」","mis":"K6-2-u4-X08"},{"t":"「‘체육’ 같은 한자어는 쓰지 않는 것이 바른 거야.」","mis":"K6-2-u4-X02"},{"t":"「어려운 외국어를 섞어 써야 발표가 멋있어.」","mis":"K6-2-u4-X03"}],"explanation":["바꿀 수 있는 말은 쉬운 우리말로 바꾸어요.","바꿀 말이 마땅치 않은 말은 그대로 써요.","목적은 누구나 알아듣게 하는 것이에요."]}'::jsonb),
('g6_2_kor_u4_L01_challenge#9','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C2',4,'essay','teacher','「우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 우리말을 바르게 쓴다는 것이 무엇인지 세 가지로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C2","difficulty":4,"kind":"essay","stem":"「우리말을 바르게 쓴다는 것은 고유어만 쓰는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 우리말을 바르게 쓴다는 것이 무엇인지 세 가지로 쓰세요.","answer_guide":{"answer":"예: 우리말에는 고유어 · 한자어 · 외래어가 모두 들어 있고, 채소나 버스처럼 다른 갈래의 낱말이 없으면 말할 수 없는 것도 많다. 그래서 고유어만 쓰는 것이 바르게 쓰는 것은 아니다. 바르게 쓴다는 것은 듣는 사람이 알아들을 수 있게 쓰는 것, 낱말의 뜻에 맞게 쓰는 것, 바꿀 수 있는 말은 쉬운 우리말로 바꾸어 쓰는 것이다.","scoring_points":["세 갈래가 함께 우리말을 이룬다는 점을 썼는가","고유어만 쓰는 것이 바르게 쓰는 것이 아닌 까닭을 썼는가","바르게 쓰기의 세 가지를 썼는가"]},"explanation":["우리말에는 세 갈래가 모두 있어요.","몰아내기가 아니라 알아듣게 쓰기예요.","뜻에 맞게, 바꿀 수 있는 말은 쉽게."]}'::jsonb),
('g6_2_kor_u4_L01_challenge#10','kor',6,2,'u4','L01','g6_2_kor_u4_L01_challenge','lesson_challenge','K6-2-u4-C3',4,'essay','teacher','말이 잘 통하지 않는 경우를 두 가지 골라 그때 생기는 일을 쓰고, 그런 일이 생기지 않게 하려면 어떻게 말하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C3","difficulty":4,"kind":"essay","stem":"말이 잘 통하지 않는 경우를 두 가지 골라 그때 생기는 일을 쓰고, 그런 일이 생기지 않게 하려면 어떻게 말하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 지나치게 줄인 말을 쓰면 아는 사람끼리만 통해서 함께 있는 사람이 대화에서 밀려난다. 굳이 어렵게 쓴 외국어를 쓰면 쉬운 우리말이 있는데도 듣는 사람이 알아듣지 못해 되묻게 된다. 그러니 듣는 사람이 누구인지 살피고, 줄인 말은 풀어서, 어려운 외국어는 쉬운 우리말로 바꾸어 말한다.","scoring_points":["말이 잘 통하지 않는 경우를 두 가지 바르게 골랐는가","각 경우에 생기는 일을 썼는가","듣는 사람을 살펴 고쳐 말하는 방법을 썼는가"]},"explanation":["네 경우를 떠올려요.","그때 누가 어떻게 곤란한지 써요.","듣는 사람의 처지에서 고쳐 말해요."]}'::jsonb),
('g6_2_kor_u4_L02_basic#1','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C4',1,'mc','auto','국어사전에서 낱말 뒤에 한자가 함께 있으면 그 낱말은 어떤 갈래인가요?',ARRAY['K6-2-u4-X05','K6-2-u4-X19']::text[],false,'{"seq":1,"concept":"K6-2-u4-C4","difficulty":1,"kind":"mc","stem":"국어사전에서 낱말 뒤에 한자가 함께 있으면 그 낱말은 어떤 갈래인가요?","options":[{"t":"한자어","correct":true},{"t":"고유어","mis":"K6-2-u4-X05"},{"t":"외래어","mis":"K6-2-u4-X05"},{"t":"방언","mis":"K6-2-u4-X19"}],"explanation":["아무것도 붙지 않으면 고유어예요.","외국어가 함께 있으면 외래어예요.","한자가 함께 있으면 한자어예요."]}'::jsonb),
('g6_2_kor_u4_L02_basic#2','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',1,'sa','auto','펌프에서 물이 나오지 않을 때 물을 끌어올리려고 위에서 붓는 물을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C5","difficulty":1,"kind":"sa","stem":"펌프에서 물이 나오지 않을 때 물을 끌어올리려고 위에서 붓는 물을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["마중물"],"explanation":["물을 마중 나간다는 말에서 왔어요.","두 낱말을 이어 보면 뜻에 가까이 갈 수 있어요.","그래서 고유어는 뜻을 짐작하기 쉬워요."],"mis":"K6-2-u4-X18"}'::jsonb),
('g6_2_kor_u4_L02_basic#3','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',1,'ox','auto','고유어는 지금도 새로 만들어질 수 있어요.',ARRAY['K6-2-u4-X06']::text[],false,'{"seq":3,"concept":"K6-2-u4-C5","difficulty":1,"kind":"ox","stem":"고유어는 지금도 새로 만들어질 수 있어요.","answer":"O","reason_options":[{"t":"고유어를 이어 붙여 새 낱말을 만들 수 있기 때문에","correct":true},{"t":"고유어는 옛날에 있던 낱말만을 말하기 때문에","mis":"K6-2-u4-X06"}],"mis":"K6-2-u4-X06","explanation":["고유어에는 처음부터 있던 낱말이 있어요.","그것을 바탕으로 만든 낱말도 있어요.","그래서 지금도 새로 만들어질 수 있어요."]}'::jsonb),
('g6_2_kor_u4_L02_basic#4','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',1,'mc','auto','「노견」을 쉬운 우리말로 다듬은 말은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X03']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":1,"kind":"mc","stem":"「노견」을 쉬운 우리말로 다듬은 말은 어느 것인가요?","options":[{"t":"갓길","correct":true},{"t":"노변","mis":"K6-2-u4-X08"},{"t":"사이드 로드","mis":"K6-2-u4-X03"},{"t":"고속 도로","mis":"K6-2-u4-X08"}],"explanation":["노견은 길의 가장자리를 말해요.","갓길이라고 하면 뜻이 바로 보여요.","그래서 누구나 알아들을 수 있어요."]}'::jsonb),
('g6_2_kor_u4_L02_basic#5','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',2,'mc','auto','이 글에서 고유어를 살펴보아야 하는 까닭으로 든 것은 어느 것인가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X06','K6-2-u4-X01']::text[],false,'{"seq":5,"concept":"K6-2-u4-C5","difficulty":2,"kind":"mc","stem":"이 글에서 고유어를 살펴보아야 하는 까닭으로 든 것은 어느 것인가요?","options":[{"t":"고유어가 우리말의 기본 바탕을 이루기 때문에","correct":true},{"t":"다른 갈래의 낱말보다 훌륭한 말이기 때문에","mis":"K6-2-u4-X07"},{"t":"옛날에만 쓰던 말이라 이제는 쓰지 않기 때문에","mis":"K6-2-u4-X06"},{"t":"낱말의 수가 가장 적기 때문에","mis":"K6-2-u4-X01"}],"explanation":["글의 첫 문장에 까닭이 있어요.","고유어는 우리말의 기본 바탕이에요.","다른 갈래보다 훌륭하다는 말은 없어요."],"asset":{"type":"passage","lines":["고유어는 우리말의 기본 바탕을 이룬다.","오랫동안 많은 사람이 써 온 낱말이라 살아온 모습과 느낌이 함께 담겨 있다.","첫째, 고유어는 뜻을 쉽게 짐작할 수 있다. 「마중물」은 물을 마중 나간다는 말에서 왔다.","둘째, 고유어는 느낌을 살려 표현할 수 있다.","같은 웃음이라도 「싱긋」과 「껄껄」은 다른 모습을 떠올리게 한다.","셋째, 고유어로 이루어진 표현에는 우리 문화와 정서가 담겨 있다."],"title":"고유어에는 어떤 가치가 있을까요?"}}'::jsonb),
('g6_2_kor_u4_L02_basic#6','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C4',2,'mc','auto','별하의 글에 나온 낱말 가운데 고유어가 아닌 것은 어느 것인가요?',ARRAY['K6-2-u4-X01']::text[],false,'{"seq":6,"concept":"K6-2-u4-C4","difficulty":2,"kind":"mc","stem":"별하의 글에 나온 낱말 가운데 고유어가 아닌 것은 어느 것인가요?","options":[{"t":"채소","correct":true},{"t":"이슬","mis":"K6-2-u4-X01"},{"t":"호미","mis":"K6-2-u4-X01"},{"t":"두둑","mis":"K6-2-u4-X01"}],"explanation":["이슬 · 호미 · 두둑은 사전에 한글 표기만 있어요.","채소는 사전에 한자가 함께 있어요.","채소는 한자어예요."],"asset":{"type":"passage","lines":["토요일 아침, 별하는 할머니를 따라 텃밭에 나갔다.","밤새 내린 이슬이 잎마다 맺혀 있었다.","할머니는 호미를 하나 건네주시며 두둑 사이의 풀을 뽑으라고 하셨다.","별하는 채소가 이렇게 촘촘히 심겨 있는 줄 몰랐다.","붉게 익은 토마토를 따서 바구니에 담았다.","일을 마치고 마루에 앉으니 등이 뻐근했다.","할머니가 웃으셨다. 「오늘은 네 덕에 일이 수월했구나.」"],"title":"별하가 토요일 아침에 겪은 일"}}'::jsonb),
('g6_2_kor_u4_L02_basic#7','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C5',2,'match','auto','고유어와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u4-C5","difficulty":2,"kind":"match","stem":"고유어와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"여울","r":"물살이 세게 흐르는 얕은 곳"},{"l":"마중물","r":"물을 끌어올리려고 위에서 붓는 물"},{"l":"손사래","r":"아니라고 할 때 손을 펴서 휘젓는 일"}],"mis":"K6-2-u4-X18","explanation":["여울은 물살이 센 얕은 곳이에요.","마중물은 물을 마중 나가는 물이에요.","세 낱말 모두 눈에 보이는 모습을 담고 있어요."]}'::jsonb),
('g6_2_kor_u4_L02_basic#8','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C7',2,'mc','auto','「손이 크다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":8,"concept":"K6-2-u4-C7","difficulty":2,"kind":"mc","stem":"「손이 크다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"씀씀이가 넉넉하다","correct":true},{"t":"손의 크기가 남보다 크다","mis":"K6-2-u4-X09"},{"t":"힘이 아주 세다","mis":"K6-2-u4-X09"},{"t":"손재주가 좋다","mis":"K6-2-u4-X09"}],"explanation":["관용 표현은 낱말 뜻을 그대로 더한 것이 아니에요.","둘 이상의 낱말이 어울려 새로운 뜻을 만들어요.","손이 크다는 씀씀이가 넉넉하다는 뜻이에요."]}'::jsonb),
('g6_2_kor_u4_L02_basic#9','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',2,'ox','auto','「컴퓨터」도 고유어로 다듬어 써야 해요.',ARRAY['K6-2-u4-X08']::text[],false,'{"seq":9,"concept":"K6-2-u4-C6","difficulty":2,"kind":"ox","stem":"「컴퓨터」도 고유어로 다듬어 써야 해요.","answer":"X","reason_options":[{"t":"바꿀 말이 마땅히 없어 그대로 쓰는 것이 더 잘 통하기 때문에","correct":true},{"t":"외래어는 모두 우리말로 바꾸어야 하기 때문에","mis":"K6-2-u4-X08"}],"mis":"K6-2-u4-X08","explanation":["다듬는 말은 쉬운 우리말이 이미 있는 말이에요.","컴퓨터는 바꿀 말이 마땅치 않아요.","그대로 쓰는 것이 오히려 잘 통해요."]}'::jsonb),
('g6_2_kor_u4_L02_basic#10','kor',6,2,'u4','L02','g6_2_kor_u4_L02_basic','lesson_basic','K6-2-u4-C6',3,'error','auto','낱말의 갈래에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X07','K6-2-u4-X02']::text[],false,'{"seq":10,"concept":"K6-2-u4-C6","difficulty":3,"kind":"error","stem":"낱말의 갈래에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「한자어를 쓰면 우리말을 해치는 거야.」","correct":true,"mis_target":"K6-2-u4-X07"},{"t":"로운 — 「세 갈래가 함께 우리말을 이루고 하는 일이 달라.」","mis":"K6-2-u4-X07"},{"t":"수아 — 「‘채소’나 ‘토마토’가 없으면 별하의 장면을 말할 수 없어.」","mis":"K6-2-u4-X02"}],"explanation":["로운과 수아는 세 갈래가 함께 쓰인다는 것을 알아요.","지안은 한자어를 나쁜 말로 여겼어요.","갈래에는 등수가 없어요."]}'::jsonb),
('g6_2_kor_u4_L02_challenge#1','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C4',2,'sa','auto','국어사전에서 낱말 뒤에 영어 같은 외국어가 함께 있으면 그 낱말은 어떤 갈래인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u4-C4","difficulty":2,"kind":"sa","stem":"국어사전에서 낱말 뒤에 영어 같은 외국어가 함께 있으면 그 낱말은 어떤 갈래인가요? 세 글자로 쓰세요.","answer":["외래어"],"explanation":["토마토를 찾으면 뒤에 영어가 함께 있어요.","다른 나라에서 들어온 말이라는 표시예요.","그래서 외래어예요."],"mis":"K6-2-u4-X05"}'::jsonb),
('g6_2_kor_u4_L02_challenge#2','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',2,'mc','auto','고유어의 가치 세 가지를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u4-X01','K6-2-u4-X07','K6-2-u4-X06']::text[],false,'{"seq":2,"concept":"K6-2-u4-C5","difficulty":2,"kind":"mc","stem":"고유어의 가치 세 가지를 바르게 모은 것은 어느 것인가요?","options":[{"t":"뜻을 쉽게 짐작할 수 있다 · 느낌을 살려 표현할 수 있다 · 우리 문화와 정서가 담겨 있다","correct":true},{"t":"글자 수가 적다 · 외국 사람도 쉽게 안다 · 사전에 없다","mis":"K6-2-u4-X01"},{"t":"다른 갈래보다 훌륭하다 · 한자어를 이긴다 · 등수가 높다","mis":"K6-2-u4-X07"},{"t":"옛날 말이라 귀하다 · 이제는 쓰지 않는다 · 새로 만들 수 없다","mis":"K6-2-u4-X06"}],"explanation":["뜻을 짐작하기 쉬워요.","느낌을 살려 표현해요.","우리 문화와 정서를 담아요."]}'::jsonb),
('g6_2_kor_u4_L02_challenge#3','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',3,'mc','auto','글쓴이가 「싱긋」과 「껄껄」을 예로 든 까닭은 어느 것인가요?',ARRAY['K6-2-u4-X18','K6-2-u4-X07']::text[],false,'{"seq":3,"concept":"K6-2-u4-C5","difficulty":3,"kind":"mc","stem":"글쓴이가 「싱긋」과 「껄껄」을 예로 든 까닭은 어느 것인가요?","options":[{"t":"고유어가 느낌을 살려 표현할 수 있다는 것을 보여 주려고","correct":true},{"t":"고유어는 뜻을 쉽게 짐작할 수 있다는 것을 보여 주려고","mis":"K6-2-u4-X18"},{"t":"웃음은 고유어로만 말할 수 있다는 것을 보여 주려고","mis":"K6-2-u4-X07"},{"t":"두 낱말의 뜻이 같다는 것을 보여 주려고","mis":"K6-2-u4-X18"}],"explanation":["「둘째」 문단에 나온 예예요.","같은 웃음도 다른 모습을 떠올리게 해요.","느낌을 살리는 가치를 보여 줘요."],"asset":{"type":"passage","lines":["고유어는 우리말의 기본 바탕을 이룬다.","오랫동안 많은 사람이 써 온 낱말이라 살아온 모습과 느낌이 함께 담겨 있다.","첫째, 고유어는 뜻을 쉽게 짐작할 수 있다. 「마중물」은 물을 마중 나간다는 말에서 왔다.","둘째, 고유어는 느낌을 살려 표현할 수 있다.","같은 웃음이라도 「싱긋」과 「껄껄」은 다른 모습을 떠올리게 한다.","셋째, 고유어로 이루어진 표현에는 우리 문화와 정서가 담겨 있다."],"title":"고유어에는 어떤 가치가 있을까요?"}}'::jsonb),
('g6_2_kor_u4_L02_challenge#4','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',3,'mc','auto','다듬으면 좋은 말과 그대로 쓰는 말을 바르게 가른 것은 어느 것인가요?',ARRAY['K6-2-u4-X08','K6-2-u4-X02','K6-2-u4-X01']::text[],false,'{"seq":4,"concept":"K6-2-u4-C6","difficulty":3,"kind":"mc","stem":"다듬으면 좋은 말과 그대로 쓰는 말을 바르게 가른 것은 어느 것인가요?","options":[{"t":"다듬으면 좋은 말 — 익일 · 회람 / 그대로 쓰는 말 — 버스 · 수학","correct":true},{"t":"다듬으면 좋은 말 — 버스 · 학교 / 그대로 쓰는 말 — 익일 · 회람","mis":"K6-2-u4-X08"},{"t":"다듬으면 좋은 말 — 모든 한자어와 외래어 / 그대로 쓰는 말 — 고유어","mis":"K6-2-u4-X02"},{"t":"다듬으면 좋은 말 — 이슬 · 호미 / 그대로 쓰는 말 — 노견","mis":"K6-2-u4-X01"}],"explanation":["쉬운 우리말이 있는데도 어렵게 쓴 말은 다듬어요.","바꿀 말이 마땅치 않은 말은 그대로 써요.","익일 · 회람은 다음 날 · 돌려보기로 다듬어요."]}'::jsonb),
('g6_2_kor_u4_L02_challenge#5','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C4',3,'ox','auto','「수월하다」는 소리가 한자어 같으니 한자어예요.',ARRAY['K6-2-u4-X05']::text[],false,'{"seq":5,"concept":"K6-2-u4-C4","difficulty":3,"kind":"ox","stem":"「수월하다」는 소리가 한자어 같으니 한자어예요.","answer":"X","reason_options":[{"t":"국어사전에 한자 없이 한글 표기만 있는 고유어이기 때문에","correct":true},{"t":"낱말의 갈래는 소리를 듣고 짐작하면 되기 때문에","mis":"K6-2-u4-X05"}],"mis":"K6-2-u4-X05","explanation":["소리로 갈래를 정하면 틀리기 쉬워요.","사전에서 확인해요.","수월하다는 한글 표기만 있는 고유어예요."]}'::jsonb),
('g6_2_kor_u4_L02_challenge#6','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',3,'match','auto','어려운 말과 쉬운 우리말로 다듬은 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C6","difficulty":3,"kind":"match","stem":"어려운 말과 쉬운 우리말로 다듬은 말을 알맞게 이으세요.","pairs":[{"l":"노견","r":"갓길"},{"l":"익일","r":"다음 날"},{"l":"회람","r":"돌려보기"},{"l":"다운로드","r":"내려받기"}],"mis":"K6-2-u4-X08","explanation":["갓길은 길의 가장자리라는 뜻이 보여요.","다음 날은 언제인지 바로 알 수 있어요.","돌려보기 · 내려받기는 하는 일이 보여요."]}'::jsonb),
('g6_2_kor_u4_L02_challenge#7','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C7',3,'error','auto','관용 표현의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X09']::text[],false,'{"seq":7,"concept":"K6-2-u4-C7","difficulty":3,"kind":"error","stem":"관용 표현의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「‘입이 짧다’는 입의 길이가 짧다는 뜻이야.」","correct":true,"mis_target":"K6-2-u4-X09"},{"t":"나은 — 「‘낯을 가리다’는 낯선 사람을 어려워한다는 뜻이야.」","mis":"K6-2-u4-X09"},{"t":"승우 — 「‘손이 크다’는 씀씀이가 넉넉하다는 뜻이야.」","mis":"K6-2-u4-X09"}],"explanation":["나은과 승우는 어울려 생긴 새 뜻을 말했어요.","태오는 낱말 뜻을 그대로 풀었어요.","입이 짧다는 음식을 심하게 가리거나 적게 먹는다는 뜻이에요."]}'::jsonb),
('g6_2_kor_u4_L02_challenge#8','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',4,'mc','auto','어려운 말을 쉬운 우리말로 다듬는 일의 목적으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X02','K6-2-u4-X08','K6-2-u4-X07']::text[],false,'{"seq":8,"concept":"K6-2-u4-C6","difficulty":4,"kind":"mc","stem":"어려운 말을 쉬운 우리말로 다듬는 일의 목적으로 알맞은 것은 어느 것인가요?","options":[{"t":"누구나 알아들을 수 있게 하는 것","correct":true},{"t":"한자어와 외래어를 우리말에서 몰아내는 것","mis":"K6-2-u4-X02"},{"t":"글자 수를 줄여 빨리 쓰는 것","mis":"K6-2-u4-X08"},{"t":"고유어가 더 훌륭하다는 것을 보이는 것","mis":"K6-2-u4-X07"}],"explanation":["다듬은 말은 뜻이 바로 드러나요.","그래서 누구나 알아들을 수 있어요.","낱말을 몰아내려는 것이 아니에요."]}'::jsonb),
('g6_2_kor_u4_L02_challenge#9','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C5',4,'essay','teacher','별하의 글에서 고유어를 세 개, 고유어가 아닌 낱말을 두 개 찾아 쓰세요. 그리고 고유어가 아닌 낱말도 이 글에 꼭 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u4-C5","difficulty":4,"kind":"essay","stem":"별하의 글에서 고유어를 세 개, 고유어가 아닌 낱말을 두 개 찾아 쓰세요. 그리고 고유어가 아닌 낱말도 이 글에 꼭 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 고유어 — 이슬 · 호미 · 두둑. 고유어가 아닌 낱말 — 채소(한자어) · 토마토(외래어). 채소와 토마토가 없으면 별하가 무엇을 보고 땄는지 그 장면을 말할 수 없다. 세 갈래가 함께 우리말을 이루고 각 갈래가 하는 일이 다르기 때문이다.","scoring_points":["고유어를 세 개 바르게 찾았는가","한자어 · 외래어를 바르게 찾았는가","세 갈래가 함께 쓰이는 까닭을 썼는가"]},"explanation":["사전 표시로 갈래를 가려요.","고유어가 아닌 말도 틀린 말이 아니에요.","갈래에는 등수가 없어요."],"asset":{"type":"passage","lines":["토요일 아침, 별하는 할머니를 따라 텃밭에 나갔다.","밤새 내린 이슬이 잎마다 맺혀 있었다.","할머니는 호미를 하나 건네주시며 두둑 사이의 풀을 뽑으라고 하셨다.","별하는 채소가 이렇게 촘촘히 심겨 있는 줄 몰랐다.","붉게 익은 토마토를 따서 바구니에 담았다.","일을 마치고 마루에 앉으니 등이 뻐근했다.","할머니가 웃으셨다. 「오늘은 네 덕에 일이 수월했구나.」"],"title":"별하가 토요일 아침에 겪은 일"}}'::jsonb),
('g6_2_kor_u4_L02_challenge#10','kor',6,2,'u4','L02','g6_2_kor_u4_L02_challenge','lesson_challenge','K6-2-u4-C6',4,'essay','teacher','학교 안내문에 「익일까지 회람 후 반납」이라고 적혀 있어요. 이 문장을 쉬운 우리말로 다듬어 쓰고, 그렇게 다듬은 까닭을 쓰세요. 그리고 같은 안내문의 「컴퓨터실」은 왜 그대로 두어도 되는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u4-C6","difficulty":4,"kind":"essay","stem":"학교 안내문에 「익일까지 회람 후 반납」이라고 적혀 있어요. 이 문장을 쉬운 우리말로 다듬어 쓰고, 그렇게 다듬은 까닭을 쓰세요. 그리고 같은 안내문의 「컴퓨터실」은 왜 그대로 두어도 되는지 쓰세요.","answer_guide":{"answer":"예: 「다음 날까지 돌려본 뒤 돌려주세요.」로 다듬는다. 익일 · 회람은 쉬운 우리말이 있는데도 어렵게 쓴 말이라, 다듬으면 나이가 많은 분이나 동생들도 무엇을 언제까지 해야 하는지 바로 알 수 있다. 컴퓨터는 바꿀 말이 마땅히 없고 바꾸면 오히려 통하지 않으므로 그대로 둔다.","scoring_points":["어려운 말을 쉬운 우리말로 바르게 다듬었는가","누구나 알아듣게 하려는 까닭을 썼는가","그대로 쓰는 말의 까닭을 썼는가"]},"explanation":["뜻이 바로 보이게 다듬어요.","목적은 누구나 알아듣게 하기예요.","바꿀 말이 없는 말은 그대로 써요."]}'::jsonb),
('g6_2_kor_u4_L04_basic#1','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',1,'mc','auto','고유어를 활용한 이름은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":1,"concept":"K6-2-u4-C8","difficulty":1,"kind":"mc","stem":"고유어를 활용한 이름은 어느 것인가요?","options":[{"t":"너른들 마을","correct":true},{"t":"그린 아파트","mis":"K6-2-u4-X10"},{"t":"제일 상가","mis":"K6-2-u4-X10"},{"t":"센트럴 공원","mis":"K6-2-u4-X10"}],"explanation":["너른들은 넓은 들이라는 고유어로 지은 이름이에요.","그린 · 센트럴은 외국어예요.","제일은 한자어예요."]}'::jsonb),
('g6_2_kor_u4_L04_basic#2','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',1,'sa','auto','조사한 내용은 유형 · 사례 · 고유어 · 고유어의 ○ 네 칸으로 정리해요. ○에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u4-C9","difficulty":1,"kind":"sa","stem":"조사한 내용은 유형 · 사례 · 고유어 · 고유어의 ○ 네 칸으로 정리해요. ○에 알맞은 한 글자를 쓰세요.","answer":["뜻"],"explanation":["유형은 동네 · 길 · 가게 · 음식 이름 가운데 하나예요.","사례와 그 속의 고유어를 적어요.","마지막 칸에는 사전에서 확인한 뜻을 적어요."],"mis":"K6-2-u4-X11"}'::jsonb),
