('g6_2_kor_u4_L04_basic#4','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',1,'mc','auto','이름의 뜻을 알아볼 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X12']::text[],false,'{"seq":4,"concept":"K6-2-u4-C9","difficulty":1,"kind":"mc","stem":"이름의 뜻을 알아볼 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"국어사전에서 찾고 어른께도 여쭈어 본다","correct":true},{"t":"글자 모양을 보고 짐작해서 정한다","mis":"K6-2-u4-X12"},{"t":"친구가 그렇다고 하면 그대로 적는다","mis":"K6-2-u4-X12"},{"t":"가장 그럴듯한 뜻을 지어 쓴다","mis":"K6-2-u4-X12"}],"explanation":["짐작한 뒤에는 반드시 확인해요.","사전 · 믿을 만한 누리집 · 어른께 여쭙기가 방법이에요.","지어 쓰면 듣는 사람이 잘못 알게 돼요."]}'::jsonb),
('g6_2_kor_u4_L04_basic#5','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',2,'mc','auto','「나루터길」을 낱말로 바르게 나눈 것은 어느 것인가요?',ARRAY['K6-2-u4-X10']::text[],false,'{"seq":5,"concept":"K6-2-u4-C8","difficulty":2,"kind":"mc","stem":"「나루터길」을 낱말로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"나루터 + 길","correct":true},{"t":"나 + 루터길","mis":"K6-2-u4-X10"},{"t":"나루 + 터길","mis":"K6-2-u4-X10"},{"t":"나눌 수 없는 한 낱말","mis":"K6-2-u4-X10"}],"explanation":["여러 낱말로 된 이름은 나누어 살펴요.","나루터는 배가 닿고 떠나는 곳이에요.","길과 이어서 나루터로 가는 길이 돼요."]}'::jsonb),
('g6_2_kor_u4_L04_basic#6','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C8',2,'match','auto','이름 속 고유어와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u4-C8","difficulty":2,"kind":"match","stem":"이름 속 고유어와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"너르다","r":"공간이 두루 다 넓다"},{"l":"나루터","r":"배가 닿고 떠나는 곳"},{"l":"새참","r":"일을 하다가 잠시 쉬며 먹는 음식"}],"mis":"K6-2-u4-X10","explanation":["너른들의 「너른」은 너르다에서 왔어요.","나루터는 배가 오가는 곳이에요.","새참은 일하다 쉬며 먹는 음식이에요."]}'::jsonb),
('g6_2_kor_u4_L04_basic#7','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',2,'mc','auto','「우리 동네 길 이름 속 고유어」를 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?',ARRAY['K6-2-u4-X13']::text[],false,'{"seq":7,"concept":"K6-2-u4-C10","difficulty":2,"kind":"mc","stem":"「우리 동네 길 이름 속 고유어」를 발표할 때 함께 보여 주면 좋은 매체는 어느 것인가요?","options":[{"t":"지도와 사진","correct":true},{"t":"글자만 빽빽하게 적은 종이","mis":"K6-2-u4-X13"},{"t":"아주 빠르게 넘기는 화면","mis":"K6-2-u4-X13"},{"t":"가사 없는 배경 음악","mis":"K6-2-u4-X13"}],"explanation":["길 이름은 어디에 있는지 함께 보여야 해요.","지도는 위치와 길의 흐름을 보여 줘요.","사진은 실제 모습을 보여 줘요."]}'::jsonb),
('g6_2_kor_u4_L04_basic#8','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C9',2,'mc','auto','조사 범위로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X11']::text[],false,'{"seq":8,"concept":"K6-2-u4-C9","difficulty":2,"kind":"mc","stem":"조사 범위로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학교에서 집까지 오는 길에 있는 가게 이름","correct":true},{"t":"우리나라에 있는 모든 가게 이름","mis":"K6-2-u4-X11"},{"t":"세계 여러 나라의 음식 이름","mis":"K6-2-u4-X11"},{"t":"정하지 않고 눈에 띄는 대로","mis":"K6-2-u4-X11"}],"explanation":["범위는 손이 닿는 곳으로 정해요.","범위를 좁게 잡을수록 뜻까지 알아볼 시간이 생겨요.","너무 넓으면 확인할 수 없어요."]}'::jsonb),
('g6_2_kor_u4_L04_basic#9','kor',6,2,'u4','L04','g6_2_kor_u4_L04_basic','lesson_basic','K6-2-u4-C10',2,'ox','auto','묻고 답하는 시간까지가 발표예요.',ARRAY['K6-2-u4-X14']::text[],false,'{"seq":9,"concept":"K6-2-u4-C10","difficulty":2,"kind":"ox","stem":"묻고 답하는 시간까지가 발표예요.","answer":"O","reason_options":[{"t":"듣는 사람이 궁금한 점을 까닭과 함께 묻고 답하며 이야기가 이어지기 때문에","correct":true},{"t":"발표하는 사람이 말을 마치면 발표가 끝나기 때문에","mis":"K6-2-u4-X14"}],"mis":"K6-2-u4-X14","explanation":["듣는 사람에게도 할 일이 있어요.","궁금한 점을 까닭과 함께 물어요.","묻고 답하기까지가 발표예요."]}'::jsonb),
