('g6_2_kor_u4_review_a#17','kor',6,2,'u4','','g6_2_kor_u4_review_a','unit_review','K6-2-u4-C9',3,'error','auto','시우네 발표 자료를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u4-X12','K6-2-u4-X10']::text[],false,'{"seq":17,"concept":"K6-2-u4-C9","difficulty":3,"kind":"error","stem":"시우네 발표 자료를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"보람 — 「‘다온 마을’은 뜻이 그럴듯하니 그대로 발표해도 돼.」","correct":true,"mis_target":"K6-2-u4-X12"},{"t":"지민 — 「‘스마일 마트’는 고유어가 아니니 다른 사례로 바꾸자.」","mis":"K6-2-u4-X10"},{"t":"현우 — 「‘솔바람길’은 낱말을 나누어 확인한 좋은 사례야.」","mis":"K6-2-u4-X10"}],"explanation":["지민과 현우는 갈래와 확인을 살폈어요.","보람은 출처 없는 뜻을 그대로 쓰자고 했어요.","그럴듯하다고 확인한 것은 아니에요."],"asset":{"type":"passage","lines":["㉠ 길 이름 · 솔바람길 · 고유어 — 솔, 바람, 길","뜻 — 소나무 사이로 바람이 지나는 길(낱말 뜻은 국어사전, 이름 유래는 구청 누리집에서 확인)","㉡ 가게 이름 · 한아름 꽃집 · 고유어 — 한아름","뜻 — 두 팔을 둥글게 벌려 껴안은 둘레(국어사전에서 확인)","㉢ 동네 이름 · 다온 마을 · 고유어 — 다온","뜻 — 좋은 일이 다 온다는 뜻이다.","㉣ 가게 이름 · 스마일 마트 · 고유어 — 스마일","뜻 — 웃음(영어 사전에서 확인)"],"title":"시우네 모둠 발표 자료 「우리 동네 이름 속 고유어」"}}'::jsonb),
