('g6_2_kor_u4_review_d#22','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C14',3,'mc','auto','언어생활을 바꾸어 가는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X21','K6-2-u4-X23','K6-2-u4-X26']::text[],false,'{"seq":22,"concept":"K6-2-u4-C14","difficulty":3,"kind":"mc","stem":"언어생활을 바꾸어 가는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 쓴 말 점검 → 지킬 수 있는 다짐 → 실천 뒤 변화한 점과 노력할 점 되돌아보기","correct":true},{"t":"친구 말 세기 → 가장 많이 쓴 친구 발표 → 끝","mis":"K6-2-u4-X21"},{"t":"크게 말하는 다짐 → 바로 끝","mis":"K6-2-u4-X23"},{"t":"홍보물 하루 붙이기 → 끝","mis":"K6-2-u4-X26"}],"explanation":["먼저 내 말을 살펴요.","지킬 수 있는 다짐을 해요.","되돌아보고 다시 해 보는 것까지가 실천이에요."]}'::jsonb),
('g6_2_kor_u4_review_d#23','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',4,'mc','auto','하람이네 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u4-X25','K6-2-u4-X27','K6-2-u4-X26']::text[],false,'{"seq":23,"concept":"K6-2-u4-C16","difficulty":4,"kind":"mc","stem":"하람이네 계획을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문구를 쉬운 우리말로 바꾸고, 꾸미기 전에 역할을 나누고, 붙인 뒤 한 주 동안 지킴이 도전을 이어 한다","correct":true},{"t":"문구는 그대로 두고 꾸밈을 더 화려하게 한다","mis":"K6-2-u4-X25"},{"t":"인쇄물 대신 한 번 틀고 마는 영상으로 바꾼다","mis":"K6-2-u4-X27"},{"t":"붙이는 날 하루만 우리말을 쓰기로 한다","mis":"K6-2-u4-X26"}],"explanation":["문구 · 역할 · 시간을 고쳐요.","내용과 방법은 그대로 살려요.","하루로 끝내지 않아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb),
('g6_2_kor_u4_review_d#24','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C16',4,'essay','teacher','하람이네 홍보물 계획에서 잘된 점 하나와 고칠 점 세 가지를 쓰고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u4-C16","difficulty":4,"kind":"essay","stem":"하람이네 홍보물 계획에서 잘된 점 하나와 고칠 점 세 가지를 쓰고, 고칠 점을 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 잘된 점 — 바꾸면 좋은 말을 알리려고 오래 붙여 두고 여러 번 보게 하는 인쇄물을 골라 내용과 방법이 잘 맞는다. 고칠 점 — 홍보 문구가 외국어라 알리려는 내용과 앞뒤가 맞지 않는다. 역할을 정하지 않고 꾸미기부터 시작했다. 붙인 날로 끝나 하루 행사가 된다. 고칠 방법 — 문구를 「쉬운 우리말로 한 번 바꾸어 말해 볼까요?」로 바꾸고, 낱말 찾기 · 글씨 쓰기 역할을 먼저 나누고, 붙인 뒤 한 주 동안 지킴이 도전을 이어 한다.","scoring_points":["잘된 점을 먼저 썼는가","문구 · 역할 · 시간의 고칠 점을 썼는가","고칠 방법을 구체적으로 썼는가"]},"explanation":["내용과 방법은 잘 맞아요.","문구 · 역할 · 시간을 고쳐요.","하루로 끝내지 않아요."],"asset":{"type":"passage","lines":["주제 — 쉬운 우리말로 바꾸어 말하기","방법 — 복도 알림판에 붙일 인쇄물","홍보 문구(초안) — 「굿 워드 챌린지! 우리말 파이팅!」","내용 — 바꾸면 좋은 말 다섯 쌍(다운로드 → 내려받기 등)","역할 — 아직 정하지 않음. 꾸미기부터 다 같이 시작","시간 — 다음 주 금요일에 붙이고 그날로 마침"],"title":"하람이네 모둠의 홍보물 계획"}}'::jsonb),
('g6_2_kor_u4_review_d#25','kor',6,2,'u4','','g6_2_kor_u4_review_d','unit_review','K6-2-u4-C17',4,'essay','teacher','「관측」과 「증발」의 뜻을 쓰고, 두 낱말을 모두 넣어 과학 시간에 있을 법한 일을 두 문장으로 쓰세요. 숫자는 쓰지 마세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u4-C17","difficulty":4,"kind":"essay","stem":"「관측」과 「증발」의 뜻을 쓰고, 두 낱말을 모두 넣어 과학 시간에 있을 법한 일을 두 문장으로 쓰세요. 숫자는 쓰지 마세요.","answer_guide":{"answer":"예: 관측 — 자연 현상을 살펴 재거나 헤아리는 일. 증발 — 액체가 그 표면에서 기체로 변하는 현상. 문장 — 「우리 모둠은 창가에 둔 물그릇을 날마다 같은 시각에 관측했다. 날이 갈수록 물이 증발해서 그릇 속 물이 줄어들었다.」","scoring_points":["두 낱말의 뜻을 바르게 썼는가","두 낱말을 뜻에 맞게 넣어 문장을 썼는가","숫자 없이 있을 법한 일로 썼는가"]},"explanation":["뜻을 정확히 알아 둬요.","문장으로 써 보면 오래 남아요.","교과서에서 다시 만나요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K6-2-u5-C1','kor',6,2,'u5',1,'음성 언어와 문자 언어 — 음성 언어는 음성으로 나타내는 말로 듣는 사람 앞에서 바로 전해지고, 문자 언어는 글자로 나타내는 말로 적어 두면 다시 볼 수 있으며, 두 언어는 등수를 매기는 사이가 아니라 알맞은 곳이 서로 다를 뿐이다',ARRAY['6국04 문법(초안)']::text[],1),
('K6-2-u5-C2','kor',6,2,'u5',1,'특성은 규칙이 아니라 기본 성질 — 말은 보통 그 자리에서 사라지고 글은 보통 오래 남지만 매체에 따라 달라져(녹음한 말은 남고, 빠르게 지나가는 대화 글·잠깐 뜨는 알림·넘기면 없어지는 자막은 흘러감) 「언제나」로 외우지 않고 이 매체에서는 어떻게 되는지를 그때그때 살핀다',ARRAY['6국04 문법(초안)']::text[],2),
('K6-2-u5-C3','kor',6,2,'u5',1,'매체 자료의 세 갈래 — 인쇄 매체는 문자 언어를 바탕으로 표·그림·사진을, 음성 매체는 음성 언어를 바탕으로 소리·음악을, 영상 매체는 음성 언어·문자 언어·그림·소리·움직임을 어울러 쓰며, 더 나은 매체는 없고 전하려는 내용과 받는 사람에 따라 알맞은 매체가 달라진다',ARRAY['6국06 매체(초안)']::text[],3),
('K6-2-u5-C4','kor',6,2,'u5',2,'문자 언어의 표현 특성 — 적은 내용이 그대로 남아 필요할 때 다시 볼 수 있고, 여러 사람이 똑같은 내용을 정확하게 나누어 가지며, 글자의 크기·굵기·문장 부호·줄 나눔으로 중요한 곳을 눈에 보이게 하고, 천천히 생각하며 읽고 쓴 뒤에 고칠 수 있다',ARRAY['6국04 문법(초안)']::text[],4),
('K6-2-u5-C5','kor',6,2,'u5',2,'음성 언어의 표현 특성 — 그 자리에서 바로 전해지고 말이 끝나면 소리가 사라지며, 목소리의 크기·억양·속도·잠깐 쉬기로 감정과 의도를 함께 전하고, 듣는 사람의 반응을 보며 말을 바꾸거나 다시 설명하고, 모르는 곳을 그 자리에서 되물을 수 있다',ARRAY['6국04 문법(초안)']::text[],5),
('K6-2-u5-C6','kor',6,2,'u5',2,'그 자리에 알맞은 방법 고르기 — 어느 쪽이 더 나은지가 아니라 전하려는 내용과 받는 사람의 처지를 함께 보아, 차례가 여럿이거나 다시 봐야 하면 글, 마음을 생생하게 전하거나 바로 주고받아야 하면 말, 어렵거나 헷갈리면 둘을 함께 쓰며, 고른 까닭을 언어의 특성과 이어 말하는 데까지가 답이다',ARRAY['6국04 문법(초안)']::text[],6),
('K6-2-u5-C7','kor',6,2,'u5',2,'두 언어를 함께 써 서로 보완하기 — 말로 설명하면 생생하지만 놓치면 되돌릴 수 없고 같은 내용을 글로도 보여 주면 놓친 곳을 다시 확인할 수 있어, 어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓴다',ARRAY['6국04 문법(초안)']::text[],7),
('K6-2-u5-C8','kor',6,2,'u5',4,'영상 매체를 이루는 요소 — 해설하는 말(흐름을 이어 줌)·자막(꼭 남겨야 할 내용을 다시 보여 줌)·장면과 움직임(어떤 일이 벌어지는지 한눈에)·소리와 음악(어디를 눈여겨볼지 알림)이 함께 내용을 전하며, 올린 날짜·만든 사람 이름·본 사람 수·화면 크기는 뜻을 나르는 요소가 아니다',ARRAY['6국06 매체(초안)']::text[],8),
('K6-2-u5-C9','kor',6,2,'u5',4,'말과 자막의 보완 · 강조 방법 — 해설하는 말은 흐름을 이어 주지만 놓치면 되돌릴 수 없어, 어렵거나 헷갈리는 내용은 자막으로 정리해 눈으로 다시 확인하게 하고, 자막은 색·크기·모양으로, 말은 음악과 효과음으로 중요한 곳을 강조한다',ARRAY['6국06 매체(초안)']::text[],9),
('K6-2-u5-C10','kor',6,2,'u5',4,'표현 효과는 무엇을 돕는가로 본다 — 자막을 화면 가득 채우거나 음악을 계속 크게 깔거나 장면을 쉴 새 없이 바꾸면 무엇이 중요한지 흐려지고, 꼭 남길 곳에만 자막을 두고 중요한 곳에서 소리를 바꾸면 또렷해지므로, 표현 효과는 요소의 개수가 아니라 그 요소가 무엇을 돕는가로 본다',ARRAY['6국06 매체(초안)']::text[],10),
('K6-2-u5-C11','kor',6,2,'u5',5,'장면마다 방법이 다른 까닭 — 같은 영상 안에서도 그 장면에서 해야 할 일이 달라 쓰는 방법이 다르다: 무엇을 다룰지 알릴 때 자막으로 제목, 처음 듣는 낱말을 정확히 남길 때 말과 자막을 함께, 느낌을 바꿀 때 음악의 빠르기를 바꾼다',ARRAY['6국06 매체(초안)']::text[],11),
('K6-2-u5-C12','kor',6,2,'u5',5,'영상 감상의 세 걸음 — 찾기(이 장면에 말·글·그림·소리 가운데 무엇이 쓰였는가)·잇기(그것이 이해를 무엇으로 돕는가)·말하기(나는 어떻게 느꼈고 까닭은 무엇인가)이며, 어느 장면이 인상 깊었는가 같은 느낌은 사람마다 다를 수 있지만 무엇이 쓰였고 무엇을 돕는가는 영상 안에서 함께 확인할 수 있으므로, 감상은 좋았다·별로였다에서 멈추지 않고 어떤 표현 때문인지 까닭을 함께 말한다',ARRAY['6국06 매체(초안)']::text[],12),
('K6-2-u5-C13','kor',6,2,'u5',5,'영상의 내용 파악하기 — 장면 차례로 무엇을 다루는지 짐작하고 낯선 낱말(밀물·썰물·퇴적·갯벌)을 먼저 익혀, 강물과 바닷물이 실어 온 고운 흙과 모래가 물살이 느린 얕은 바닥에 오랫동안 쌓여 갯벌이 만들어지고 그곳에 게·조개·갯지렁이가 산다는 내용을 정확히 확인하며 본다',ARRAY['6국06 매체(초안)']::text[],13),
('K6-2-u5-C14','kor',6,2,'u5',7,'독자를 고려한다는 것 — 글을 읽는 사람(독자)의 처지에서 헤아려 보는 것으로, 독자의 흥미·배경지식·수준(알아들을 수 있는 낱말과 표현)·글을 읽는 매체를 살피고, 독자가 겪는 어려움과 독자가 할 수 있는 일까지 보이게 쓴다 — 같은 내용이라도 누가 읽느냐에 따라 낱말도 차례도 달라진다',ARRAY['6국03 쓰기(초안)']::text[],14),
('K6-2-u5-C15','kor',6,2,'u5',7,'독자 고려는 비위 맞추기가 아니다 — 독자가 좋아할 내용만 고르거나 어려운 이야기를 빼 버리거나 낱말만 쉽게 바꾸면 끝나는 것이 아니라, 전하려는 것은 그대로 두고 독자가 알아들을 수 있게 짜는 것이며, 말하고 싶은 것을 줄이는 일이 아니라 그것이 독자에게 닿게 하는 일이다',ARRAY['6국03 쓰기(초안)']::text[],15),
('K6-2-u5-C16','kor',6,2,'u5',7,'글 쓰는 세 단계와 고쳐 쓰기 — 계획 세우기(누가 읽을지·무엇을 왜 쓸지)·내용 생성하고 조직하기(쓸 거리를 모아 차례 짜기)·글 쓰고 고쳐 쓰기를 거치며 단계마다 독자를 다시 떠올리고, 고쳐 쓸 때에는 독자의 수준에 맞는가·주제가 드러나는가·낱말과 문장에 잘못이 없는가·오해할 만한 표현이 없는가를 본다 — 고쳐 쓰기는 틀린 곳을 벌하는 일이 아니라 독자에게 더 잘 닿게 하는 일',ARRAY['6국03 쓰기(초안)']::text[],16),
('K6-2-u5-C17','kor',6,2,'u5',7,'글에 자료를 넣는 까닭 — 글만으로 잘 전해지지 않을 때 수를 견줄 때는 표나 그래프, 모습이나 차례는 사진이나 그림, 할 일은 기호와 줄 나눔을 함께 놓으며, 자료는 개수를 채우려고가 아니라 독자의 이해를 도우려고 넣고 글에서 말한 내용과 이어지는 것만 고른다',ARRAY['6국03 쓰기(초안)']::text[],17),
('K6-2-u5-C18','kor',6,2,'u5',9,'기사문의 특성 — 어떤 사실이나 사건을 여러 사람에게 알리는 글로, 직접 보고 듣고 조사한 내용을, 느낌이 아니라 사실로, 빠르고 정확하게, 객관적이고 간결한 표현으로 쓰며, 읽는 사람이 사실이라고 믿고 읽기 때문에 지어낼 수 없다',ARRAY['6국03 쓰기(초안)']::text[],18),
('K6-2-u5-C19','kor',6,2,'u5',9,'기사문의 짜임과 육하원칙 — 제목(표제는 내용을 간결하게 드러내고 부제는 필요할 때 표제를 보충)·전문(주요 내용을 누가·언제·어디에서·무엇을·어떻게·왜의 육하원칙으로 앞에서 요약)·본문(주된 내용을 자세히)으로 이루어진다',ARRAY['6국03 쓰기(초안)']::text[],19),
('K6-2-u5-C20','kor',6,2,'u5',9,'확인한 사실과 생각 가르기 — 직접 세어 본 수·직접 들은 말·눈으로 확인한 일·본인에게 물어 확인한 계획은 쓰고, 확인하지 못한 소문·그럴 것 같아 지어낸 숫자는 쓰지 않으며, 「모두 기뻐했다」처럼 쓴 사람의 생각을 사실처럼 쓰지 않고 생각을 쓰려면 누구의 생각인지 밝힌다',ARRAY['6국03 쓰기(초안)']::text[],20),
('K6-2-u5-C21','kor',6,2,'u5',9,'기사문 계획 · 자료 출처 · 제목 — 독자의 특성·기삿거리(독자가 관심 있고 내가 가서 확인할 수 있는 일)·필요한 자료·자료 수집 방법을 정한 뒤 개요를 짜고, 사진·표 같은 자료는 출처(내가 조사했으면 언제·누구에게·어떻게)를 밝히며, 제목은 내용을 담고 읽고 싶어지게 쓰되 본문에 없는 말로 부풀리지 않는다',ARRAY['6국03 쓰기(초안)']::text[],21),
('K6-2-u5-C22','kor',6,2,'u5',12,'편지의 짜임과 독자 — 받는 사람·첫인사(안부)·하고 싶은 말(쓴 목적)·끝인사·쓴 날짜와 보내는 사람의 다섯 부분으로 이루어지며, 독자가 받는 사람 한 사람이라 알맞은 높임말을 쓰고 목적이 뚜렷이 드러나게 하고 받는 사람이 모를 만한 일은 앞뒤를 설명해 준다',ARRAY['6국03 쓰기(초안)']::text[],22),
('K6-2-u5-C23','kor',6,2,'u5',12,'전하려는 마음에 맞는 내용 — 고마울 때는 무엇이 고마웠는지 그 일을 콕 집어, 미안할 때는 변명보다 무엇이 잘못이었는지를 먼저, 축하할 때는 그 사람이 애쓴 과정을 함께, 힘을 내라고 할 때는 섣부른 충고보다 곁에 있다는 말을 쓴다',ARRAY['6국03 쓰기(초안)']::text[],23),
('K6-2-u5-C24','kor',6,2,'u5',12,'편지의 매체 고르기와 건네기 — 손 편지(글씨와 종이가 남아 오래 간직)·영상 편지(목소리와 표정이 생생)·누리집이나 게시판 글(여러 사람이 함께 봄) 가운데 전하려는 마음과 받는 사람의 처지에 맞는 것을 고르며(매체에 등수 없음), 정말 전하고 싶은 사람에게 쓰고 실제로 건네 반응을 보아야 편지가 완성된다',ARRAY['6국03 쓰기(초안)']::text[],24),
('K6-2-u5-C25','kor',6,2,'u5',12,'겹받침이 있는 낱말의 발음 — 받침에 자음자가 두 개 있는 겹받침은 받침에서 한 번에 한 소리만 낼 수 있어 뒤에 자음자가 오거나 낱말이 끝나면 하나만 소리 나고(붉다[북따]·얇다[얄따]·짧다[짤따]), 뒤에 모음이 오면 두 소리가 다 나며 뒤엣것이 뒷글자로 넘어간다(붉어요[불거요]·얇아요[얄바요]) (기초 다지기)',ARRAY['6국04 문법(초안)']::text[],25)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K6-2-u5-X01','kor',6,'u5',ARRAY['K6-2-u5-C1']::text[],'음성 언어와 문자 언어의 뜻을 서로 바꾸어 알거나, 글로 옮겨 적은 말을 음성 언어로 여긴다','음성으로? 글자로?'),
('K6-2-u5-X02','kor',6,'u5',ARRAY['K6-2-u5-C2','K6-2-u5-C4','K6-2-u5-C5']::text[],'「말은 언제나 사라진다 · 글은 언제나 남는다」처럼 특성을 어떤 경우에도 맞는 규칙으로 외워, 녹음한 말이나 흘러가는 글을 설명하지 못한다','보통은 그렇지만 매체에 따라 달라져요'),
('K6-2-u5-X03','kor',6,'u5',ARRAY['K6-2-u5-C1','K6-2-u5-C3','K6-2-u5-C24']::text[],'글이 말보다, 영상이 글보다 낫다처럼 언어나 매체에 등수를 매긴다','더 나은 쪽이 아니라 그 자리에 알맞은 쪽'),
('K6-2-u5-X04','kor',6,'u5',ARRAY['K6-2-u5-C3']::text[],'인쇄 · 음성 · 영상 매체가 주로 쓰는 방법을 헷갈린다','무엇을 바탕으로 무엇을 더하나?'),
('K6-2-u5-X05','kor',6,'u5',ARRAY['K6-2-u5-C3','K6-2-u5-C8']::text[],'올린 날짜 · 만든 사람 이름 · 본 사람 수 · 화면 크기처럼 뜻을 나르지 않는 것을 매체 자료의 표현 방법으로 고른다','화면이나 지면에서 뜻을 나르는 것만'),
('K6-2-u5-X06','kor',6,'u5',ARRAY['K6-2-u5-C4','K6-2-u5-C5']::text[],'글의 강조 방법(굵은 글씨 · 밑줄 · 문장 부호)과 말의 강조 방법(목소리 크기 · 억양 · 속도)을 뒤섞는다','글은 눈에, 말은 귀에 띄게'),
('K6-2-u5-X07','kor',6,'u5',ARRAY['K6-2-u5-C4']::text[],'문자 언어의 장점(다시 보기 · 똑같이 나누어 갖기 · 천천히 읽고 고치기)을 모르거나 글은 쓰고 나면 고칠 수 없다고 여긴다','적어 두면 무엇이 좋을까?'),
('K6-2-u5-X08','kor',6,'u5',ARRAY['K6-2-u5-C5']::text[],'음성 언어의 장점(목소리로 감정 전하기 · 반응 보고 바꾸기 · 그 자리에서 되묻기)을 모른다','마주 보고 말하면 무엇을 할 수 있을까?'),
('K6-2-u5-X09','kor',6,'u5',ARRAY['K6-2-u5-C6']::text[],'알맞은 방법을 고르기만 하고 까닭을 말하지 않거나, 까닭을 언어의 특성과 잇지 못한다','고른 것 + 그 특성 때문에'),
('K6-2-u5-X10','kor',6,'u5',ARRAY['K6-2-u5-C6','K6-2-u5-C24']::text[],'전하려는 내용과 받는 사람의 처지를 보지 않고 늘 한 가지 방법만 쓰거나 빠르고 편한 방법만 고른다','무엇을 · 누구에게?'),
('K6-2-u5-X11','kor',6,'u5',ARRAY['K6-2-u5-C7','K6-2-u5-C9']::text[],'말한 내용을 글(자막)로도 보여 주면 겹쳐서 쓸모없다고 여겨, 두 언어가 서로 보완하는 것을 모른다','놓친 곳을 다시 확인하게'),
('K6-2-u5-X12','kor',6,'u5',ARRAY['K6-2-u5-C8','K6-2-u5-C9','K6-2-u5-C11']::text[],'해설하는 말 · 자막 · 장면 · 소리와 음악이 각각 하는 일을 헷갈린다','흐름 · 붙들기 · 한눈에 · 눈여겨볼 곳'),
('K6-2-u5-X13','kor',6,'u5',ARRAY['K6-2-u5-C10','K6-2-u5-C17']::text[],'자막 · 음악 · 장면 · 자료를 많이 넣을수록 잘 전달되고 좋은 자료라고 여긴다','개수가 아니라 무엇을 돕는가'),
('K6-2-u5-X14','kor',6,'u5',ARRAY['K6-2-u5-C11']::text[],'장면마다 방법을 아무렇게나 골랐다고 여겨, 그 장면에서 해야 할 일과 방법을 잇지 못한다','이 장면에서 시청자가 알아야 할 것은?'),
('K6-2-u5-X15','kor',6,'u5',ARRAY['K6-2-u5-C12']::text[],'감상을 「좋았다 · 재미있었다 · 별로였다」에서 멈추고 어떤 표현 때문인지 까닭을 말하지 않는다','찾기 · 잇기 · 말하기'),
('K6-2-u5-X16','kor',6,'u5',ARRAY['K6-2-u5-C12']::text[],'느낌이 나와 다르면 잘못 본 것이라 여기거나, 사람마다 다를 수 있는 느낌과 영상 안에서 확인할 수 있는 것을 가르지 못한다','갈릴 수 있는 것 · 함께 확인할 수 있는 것'),
('K6-2-u5-X17','kor',6,'u5',ARRAY['K6-2-u5-C13']::text[],'영상의 장면 차례를 이어 보지 않아 갯벌이 만들어지는 과정을 잘못 안다(솟아올라서 · 얼었다 녹아서 등)','무엇이 어디에 오래 쌓이나?'),
('K6-2-u5-X18','kor',6,'u5',ARRAY['K6-2-u5-C13']::text[],'영상에 나온 낱말(밀물 · 썰물 · 퇴적 · 갯벌)의 뜻을 서로 헷갈린다','들어오는 물 · 나가는 물 · 쌓이는 일'),
('K6-2-u5-X19','kor',6,'u5',ARRAY['K6-2-u5-C14']::text[],'독자 고려를 낱말만 쉽게 바꾸는 일로 좁히거나, 독자의 흥미 · 배경지식 · 수준 · 매체 가운데 일부만 살핀다','흥미 · 배경지식 · 수준 · 매체'),
('K6-2-u5-X20','kor',6,'u5',ARRAY['K6-2-u5-C15']::text[],'독자 고려를 독자가 좋아할 내용만 고르거나 어려운 이야기를 빼 버리는 비위 맞추기로 여긴다','전하려는 것은 그대로, 닿는 방법을 바꾸기'),
('K6-2-u5-X21','kor',6,'u5',ARRAY['K6-2-u5-C16']::text[],'글 쓰는 세 단계와 그 단계에서 하는 일을 헷갈리거나, 독자는 처음 계획할 때만 떠올리면 된다고 여긴다','쓰기 전 · 쓰는 중 · 쓴 뒤, 단계마다 독자'),
('K6-2-u5-X22','kor',6,'u5',ARRAY['K6-2-u5-C16']::text[],'고쳐 쓸 곳을 글씨 · 길이 · 꾸밈 같은 겉모습에서 찾거나, 고쳐 쓰기를 틀린 곳을 벌하는 일로 여긴다','독자에게 더 잘 닿게 하려고 고쳐요'),
('K6-2-u5-X23','kor',6,'u5',ARRAY['K6-2-u5-C17']::text[],'자료를 개수를 채우려고 넣거나, 글과 이어지지 않는 자료를 넣거나, 자료를 넣으면 글을 덜 써도 된다고 여긴다','글만으로 어려운 곳을 돕는 자료'),
('K6-2-u5-X24','kor',6,'u5',ARRAY['K6-2-u5-C14','K6-2-u5-C16']::text[],'어렵고 딱딱한 낱말을 많이 쓰면 글이 훌륭해 보인다고 여겨, 독자가 알아듣지 못하는 문제를 보지 않는다','독자가 아는 말인가?'),
('K6-2-u5-X25','kor',6,'u5',ARRAY['K6-2-u5-C14','K6-2-u5-C15']::text[],'글에서 독자가 무엇을 하면 되는지, 왜 그래야 하는지가 빠져도 괜찮다고 여긴다','까닭과 할 일이 함께 보이게'),
('K6-2-u5-X26','kor',6,'u5',ARRAY['K6-2-u5-C18','K6-2-u5-C20']::text[],'기사문에 쓴 사람의 느낌이나 생각을 사실처럼 쓴다(「모두 기뻐했다」 · 「가장 큰 변화」)','누구든 다시 확인할 수 있는가?'),
('K6-2-u5-X27','kor',6,'u5',ARRAY['K6-2-u5-C18','K6-2-u5-C20']::text[],'확인하지 못한 소문이나 그럴 것 같아 지어낸 숫자를 기사문에 쓴다','세어 보거나 물어본 것만'),
('K6-2-u5-X28','kor',6,'u5',ARRAY['K6-2-u5-C19']::text[],'기사문의 짜임(표제 · 부제 · 전문 · 본문)과 하는 일을 헷갈리거나, 전문을 느낌이나 못다 한 말을 쓰는 곳으로 여긴다','전문 = 주요 내용 요약'),
('K6-2-u5-X29','kor',6,'u5',ARRAY['K6-2-u5-C19']::text[],'육하원칙(누가 · 언제 · 어디에서 · 무엇을 · 어떻게 · 왜)의 항목을 서로 헷갈리거나 빠뜨린다','여섯 가지 물음에 하나씩 답하기'),
('K6-2-u5-X30','kor',6,'u5',ARRAY['K6-2-u5-C21']::text[],'기삿거리를 독자의 관심이나 직접 확인할 수 있는지를 보지 않고 고른다','독자가 관심 있고, 내가 가서 확인할 수 있는 일'),
('K6-2-u5-X31','kor',6,'u5',ARRAY['K6-2-u5-C21']::text[],'기사문 제목을 본문에 없는 말로 부풀리거나, 반대로 아무 내용도 담지 않은 제목을 쓴다','내용을 담되 부풀리지 않기'),
('K6-2-u5-X32','kor',6,'u5',ARRAY['K6-2-u5-C21','K6-2-u5-C17']::text[],'사진 · 표 같은 자료를 넣으면서 어디에서 얻었는지, 언제 누구에게 어떻게 조사했는지 출처를 밝히지 않는다','출처를 밝혀요'),
('K6-2-u5-X33','kor',6,'u5',ARRAY['K6-2-u5-C22']::text[],'편지의 다섯 부분(받는 사람 · 첫인사 · 하고 싶은 말 · 끝인사 · 쓴 날짜와 보내는 사람)을 빠뜨리거나 하는 일을 헷갈린다','누구에게 · 인사 · 목적 · 인사 · 언제 누가'),
('K6-2-u5-X34','kor',6,'u5',ARRAY['K6-2-u5-C22']::text[],'편지를 받는 사람에게 알맞은 높임말을 쓰지 않거나, 받는 사람이 모를 만한 일을 앞뒤 설명 없이 쓴다','받는 사람 한 사람을 떠올려요'),
('K6-2-u5-X35','kor',6,'u5',ARRAY['K6-2-u5-C23']::text[],'전하려는 마음과 맞지 않는 내용을 쓴다(축하에 충고, 사과에 변명 먼저, 위로에 섣부른 충고)','이 마음에 맞는 말은?'),
('K6-2-u5-X36','kor',6,'u5',ARRAY['K6-2-u5-C23']::text[],'「고마워」 · 「잘했네」처럼 무엇이 그런지 없이 막연하게 써서 마음이 잘 닿지 않는다','그 일을 콕 집어'),
('K6-2-u5-X37','kor',6,'u5',ARRAY['K6-2-u5-C24']::text[],'편지를 숙제로 아무에게나 쓰거나 꾸미기에 시간을 다 쓰고, 건네고 반응을 보는 것을 하지 않는다','건네고 나서 완성돼요'),
('K6-2-u5-X38','kor',6,'u5',ARRAY['K6-2-u5-C25']::text[],'겹받침 뒤에 자음자가 오거나 낱말이 끝날 때에도 두 소리를 다 내거나, 뒤에 모음이 와도 하나만 소리 낸다','뒤에 오는 것이 자음자? 모음?'),
('K6-2-u5-X39','kor',6,'u5',ARRAY['K6-2-u5-C25']::text[],'겹받침 낱말에서 어느 자음자가 소리 나는지, 뒤엣것이 어느 글자로 넘어가는지를 헷갈린다','소리 내어 천천히 읽어 보기'),
('K6-2-u5-X40','kor',6,'u5',ARRAY['K6-2-u5-C16','K6-2-u5-C24']::text[],'「앞으로 열심히 하겠다」처럼 언제 · 어디에서 · 무엇을 할지 없는 다짐을 실천 계획으로 여긴다','언제 · 어디에서 · 무엇을')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_2_kor_u5_L01_basic#1','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'mc','auto','「음성 언어」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X04']::text[],false,'{"seq":1,"concept":"K6-2-u5-C1","difficulty":1,"kind":"mc","stem":"「음성 언어」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"음성으로 나타내는 말","correct":true},{"t":"글자로 나타내는 말","mis":"K6-2-u5-X01"},{"t":"그림과 사진으로 나타내는 것","mis":"K6-2-u5-X04"},{"t":"어느 고장에서만 쓰는 말","mis":"K6-2-u5-X01"}],"explanation":["글자로 나타내는 말은 문자 언어예요.","그림과 사진은 언어가 아니라 함께 쓰는 자료예요.","음성으로 나타내는 말이 음성 언어예요."]}'::jsonb),
('g6_2_kor_u5_L01_basic#2','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'sa','auto','글자로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u5-C1","difficulty":1,"kind":"sa","stem":"글자로 나타내는 말을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["문자언어","문자 언어"],"explanation":["음성으로 나타내는 말은 음성 언어예요.","글자로 나타내는 말은 문자 언어예요.","적어 두면 다시 볼 수 있어요."],"mis":"K6-2-u5-X01"}'::jsonb),
('g6_2_kor_u5_L01_basic#3','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',1,'ox','auto','음성 언어와 문자 언어 가운데 문자 언어가 더 좋은 언어예요.',ARRAY['K6-2-u5-X03']::text[],false,'{"seq":3,"concept":"K6-2-u5-C1","difficulty":1,"kind":"ox","stem":"음성 언어와 문자 언어 가운데 문자 언어가 더 좋은 언어예요.","answer":"X","reason_options":[{"t":"두 언어는 알맞은 곳이 서로 다를 뿐이기 때문에","correct":true},{"t":"글은 남고 말은 사라지기 때문에","mis":"K6-2-u5-X03"}],"mis":"K6-2-u5-X03","explanation":["두 언어는 등수를 매기는 사이가 아니에요.","상황마다 알맞은 쪽이 달라요.","그래서 더 좋은 언어는 없어요."]}'::jsonb),
('g6_2_kor_u5_L01_basic#4','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C3',1,'mc','auto','음성 언어를 바탕으로 소리와 음악을 함께 쓰는 매체는 어느 것인가요?',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":4,"concept":"K6-2-u5-C3","difficulty":1,"kind":"mc","stem":"음성 언어를 바탕으로 소리와 음악을 함께 쓰는 매체는 어느 것인가요?","options":[{"t":"음성 매체","correct":true},{"t":"인쇄 매체","mis":"K6-2-u5-X04"},{"t":"영상 매체","mis":"K6-2-u5-X04"},{"t":"문자 매체","mis":"K6-2-u5-X04"}],"explanation":["인쇄 매체는 문자 언어를 바탕으로 해요.","영상 매체는 여러 방법이 어우러져요.","소리로 전하는 라디오 같은 것이 음성 매체예요."]}'::jsonb),
('g6_2_kor_u5_L01_basic#5','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C1',2,'mc','auto','시율이와 도아가 준비물을 다시 확인할 수 있었던 까닭은 무엇인가요?',ARRAY['K6-2-u5-X08','K6-2-u5-X09','K6-2-u5-X02']::text[],false,'{"seq":5,"concept":"K6-2-u5-C1","difficulty":2,"kind":"mc","stem":"시율이와 도아가 준비물을 다시 확인할 수 있었던 까닭은 무엇인가요?","options":[{"t":"같은 내용이 글로도 남아 있었기 때문에","correct":true},{"t":"선생님의 목소리가 아주 컸기 때문에","mis":"K6-2-u5-X08"},{"t":"두 사람의 기억력이 좋았기 때문에","mis":"K6-2-u5-X09"},{"t":"말은 언제나 남기 때문에","mis":"K6-2-u5-X02"}],"explanation":["두 사람은 앞부분만 기억났어요.","알림 게시글을 다시 읽어 보기로 했어요.","글로 남은 내용은 다시 볼 수 있어요."],"asset":{"type":"speech","turns":[{"who":"시율","text":"도아야, 아까 선생님이 준비물 말씀하셨잖아. 뭐였지?"},{"who":"도아","text":"나도 앞부분만 기억나. 잠깐, 알림 게시글에도 올라와 있어."},{"who":"시율","text":"아, 글로도 올려 주셨구나. 그럼 다시 읽어 보면 되겠다."},{"who":"도아","text":"응. 말씀은 지나갔지만 글은 그대로 남아 있으니까."}]}}'::jsonb),
('g6_2_kor_u5_L01_basic#6','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C6',2,'match','auto','상황과 알맞은 방법을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C6","difficulty":2,"kind":"match","stem":"상황과 알맞은 방법을 이으세요.","pairs":[{"l":"여러 사람이 오래 기억해야 할 준비물 안내","r":"글로 적어 둡니다"},{"l":"다친 친구에게 지금 걱정하는 마음 전하기","r":"직접 말로 전합니다"},{"l":"실험 차례를 보여 주며 설명하기","r":"말과 글을 함께 씁니다"}],"mis":"K6-2-u5-X10","explanation":["다시 봐야 하는 안내는 글이 알맞아요.","지금 마음을 전할 때는 말이 알맞아요.","차례가 헷갈리는 설명은 둘을 함께 써요."]}'::jsonb),
('g6_2_kor_u5_L01_basic#7','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C2',2,'mc','auto','다음 가운데 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03']::text[],false,'{"seq":7,"concept":"K6-2-u5-C2","difficulty":2,"kind":"mc","stem":"다음 가운데 알맞게 말한 것은 어느 것인가요?","options":[{"t":"음성 메모로 남기면 말도 다시 들을 수 있다","correct":true},{"t":"말은 어떤 경우에도 다시 확인할 수 없다","mis":"K6-2-u5-X02"},{"t":"글은 어떤 경우에도 사라지지 않는다","mis":"K6-2-u5-X02"},{"t":"남는 쪽이 언제나 더 좋은 방법이다","mis":"K6-2-u5-X03"}],"explanation":["말은 보통 그 자리에서 사라져요.","그래도 녹음하면 남아요.","특성은 규칙이 아니라 기본 성질이에요."]}'::jsonb),
('g6_2_kor_u5_L01_basic#8','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C8',2,'mc','auto','매체 자료가 내용을 전달할 때 쓰는 방법이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":8,"concept":"K6-2-u5-C8","difficulty":2,"kind":"mc","stem":"매체 자료가 내용을 전달할 때 쓰는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"파일에 붙인 이름","correct":true},{"t":"말하는 사람의 목소리","mis":"K6-2-u5-X05"},{"t":"화면에 뜨는 자막","mis":"K6-2-u5-X05"},{"t":"배경에 깔리는 음악","mis":"K6-2-u5-X05"}],"explanation":["목소리 · 자막 · 음악은 뜻을 나르는 방법이에요.","파일 이름은 화면에서 뜻을 나르지 않아요.","뜻을 나르는 것만 골라요."]}'::jsonb),
('g6_2_kor_u5_L01_basic#9','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C3',2,'ox','auto','영상 매체는 음성 언어와 문자 언어에 그림 · 소리 · 움직임이 어우러진 매체예요.',ARRAY['K6-2-u5-X04']::text[],false,'{"seq":9,"concept":"K6-2-u5-C3","difficulty":2,"kind":"ox","stem":"영상 매체는 음성 언어와 문자 언어에 그림 · 소리 · 움직임이 어우러진 매체예요.","answer":"O","reason_options":[{"t":"여러 방법을 함께 써서 내용을 전하기 때문에","correct":true},{"t":"글자만 써서 내용을 전하기 때문에","mis":"K6-2-u5-X04"}],"mis":"K6-2-u5-X04","explanation":["영상에는 말도 글도 들어 있어요.","그림과 소리, 움직임도 함께 있어요.","그래서 여러 방법이 어우러진 매체예요."]}'::jsonb),
('g6_2_kor_u5_L01_basic#10','kor',6,2,'u5','L01','g6_2_kor_u5_L01_basic','lesson_basic','K6-2-u5-C2',3,'error','auto','이 단원의 약속에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03']::text[],false,'{"seq":10,"concept":"K6-2-u5-C2","difficulty":3,"kind":"error","stem":"이 단원의 약속에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「말은 언제나 없어지고 글은 언제나 남으니까 그대로 외우면 돼.」","correct":true,"mis_target":"K6-2-u5-X02"},{"t":"리안 — 「녹음한 말은 남고, 빠르게 지나가는 대화 글은 흘러가기도 해.」","mis":"K6-2-u5-X02"},{"t":"하진 — 「그 자리에 무엇이 알맞은지를 살펴보면 돼.」","mis":"K6-2-u5-X03"}],"explanation":["리안과 하진은 약속을 바르게 말했어요.","태오는 특성을 규칙으로 외웠어요.","보통은 그렇지만 매체에 따라 달라져요."]}'::jsonb),
('g6_2_kor_u5_L01_challenge#1','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C14',2,'mc','auto','글을 읽는 사람을 무엇이라고 하나요?',ARRAY['K6-2-u5-X19']::text[],false,'{"seq":1,"concept":"K6-2-u5-C14","difficulty":2,"kind":"mc","stem":"글을 읽는 사람을 무엇이라고 하나요?","options":[{"t":"독자","correct":true},{"t":"작가","mis":"K6-2-u5-X19"},{"t":"기자","mis":"K6-2-u5-X19"},{"t":"화자","mis":"K6-2-u5-X19"}],"explanation":["글을 쓰는 사람은 글쓴이예요.","글을 읽는 사람은 독자예요.","같은 내용도 누가 읽느냐에 따라 달라져요."]}'::jsonb),
('g6_2_kor_u5_L01_challenge#2','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',2,'mc','auto','인쇄 매체가 주로 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X04','K6-2-u5-X05']::text[],false,'{"seq":2,"concept":"K6-2-u5-C3","difficulty":2,"kind":"mc","stem":"인쇄 매체가 주로 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"문자 언어를 바탕으로 표 · 그림 · 사진을 함께 쓴다","correct":true},{"t":"음성 언어를 바탕으로 소리와 음악을 함께 쓴다","mis":"K6-2-u5-X04"},{"t":"말 · 글 · 소리 · 움직임을 모두 어울러 쓴다","mis":"K6-2-u5-X04"},{"t":"파일 이름과 올린 날짜로 내용을 전한다","mis":"K6-2-u5-X05"}],"explanation":["책과 신문은 인쇄 매체예요.","글자를 바탕으로 해요.","표 · 그림 · 사진을 함께 써요."]}'::jsonb),
('g6_2_kor_u5_L01_challenge#3','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C2',3,'mc','auto','「글인데 흘러가는 경우」로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X01']::text[],false,'{"seq":3,"concept":"K6-2-u5-C2","difficulty":3,"kind":"mc","stem":"「글인데 흘러가는 경우」로 알맞은 것은 어느 것인가요?","options":[{"t":"잠깐 떴다 사라지는 휴대 전화 알림","correct":true},{"t":"도서관에 꽂힌 책","mis":"K6-2-u5-X02"},{"t":"학급 게시판에 붙은 안내문","mis":"K6-2-u5-X02"},{"t":"녹음해 둔 음성 메모","mis":"K6-2-u5-X01"}],"explanation":["책과 게시판의 글은 오래 남아요.","음성 메모는 말인데 남는 경우예요.","잠깐 뜨고 사라지는 알림은 글인데 흘러가요."]}'::jsonb),
('g6_2_kor_u5_L01_challenge#4','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C6',3,'mc','auto','내일 소풍 장소와 모일 시각을 반 전체에 알리려고 해요. 어떤 방법이 가장 알맞나요?',ARRAY['K6-2-u5-X10','K6-2-u5-X03']::text[],false,'{"seq":4,"concept":"K6-2-u5-C6","difficulty":3,"kind":"mc","stem":"내일 소풍 장소와 모일 시각을 반 전체에 알리려고 해요. 어떤 방법이 가장 알맞나요?","options":[{"t":"말로 알리고 같은 내용을 글로도 적어 둔다","correct":true},{"t":"말로만 한 번 크게 알린다","mis":"K6-2-u5-X10"},{"t":"가장 빨리 할 수 있는 방법이면 무엇이든 괜찮다","mis":"K6-2-u5-X10"},{"t":"글이 말보다 좋으니 글로만 알린다","mis":"K6-2-u5-X03"}],"explanation":["여러 사람이 오래 기억해야 하는 내용이에요.","말로 알리면 그 자리에서 되물을 수 있어요.","글로도 적어 두면 놓친 사람이 다시 볼 수 있어요."]}'::jsonb),
('g6_2_kor_u5_L01_challenge#5','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C8',3,'ox','auto','영상을 올린 날짜도 그 영상이 내용을 전하는 표현 방법이에요.',ARRAY['K6-2-u5-X05']::text[],false,'{"seq":5,"concept":"K6-2-u5-C8","difficulty":3,"kind":"ox","stem":"영상을 올린 날짜도 그 영상이 내용을 전하는 표현 방법이에요.","answer":"X","reason_options":[{"t":"화면에서 뜻을 나르는 요소가 아니기 때문에","correct":true},{"t":"영상에 관한 것은 모두 표현 방법이기 때문에","mis":"K6-2-u5-X05"}],"mis":"K6-2-u5-X05","explanation":["표현 방법은 화면이나 소리로 뜻을 나르는 것이에요.","올린 날짜는 영상 밖의 정보예요.","목소리 · 자막 · 음악 · 장면을 찾아요."]}'::jsonb),
('g6_2_kor_u5_L01_challenge#6','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',3,'match','auto','매체와 그 매체의 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u5-C3","difficulty":3,"kind":"match","stem":"매체와 그 매체의 예를 알맞게 이으세요.","pairs":[{"l":"인쇄 매체","r":"신문과 책"},{"l":"음성 매체","r":"라디오 방송"},{"l":"영상 매체","r":"공익 안내 영상"}],"mis":"K6-2-u5-X04","explanation":["신문과 책은 글자를 바탕으로 해요.","라디오는 소리로 전해요.","영상은 말 · 글 · 그림 · 소리가 어우러져요."]}'::jsonb),
('g6_2_kor_u5_L01_challenge#7','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C3',3,'error','auto','매체에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u5-X03','K6-2-u5-X10']::text[],false,'{"seq":7,"concept":"K6-2-u5-C3","difficulty":3,"kind":"error","stem":"매체에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서준 — 「여러 방법을 다 쓰니까 영상 매체가 언제나 제일 좋아.」","correct":true,"mis_target":"K6-2-u5-X03"},{"t":"나윤 — 「전하려는 내용에 따라 알맞은 매체가 달라.」","mis":"K6-2-u5-X03"},{"t":"은재 — 「받는 사람이 누구인지도 함께 봐야 해.」","mis":"K6-2-u5-X10"}],"explanation":["나윤과 은재는 바르게 말했어요.","서준은 매체에 등수를 매겼어요.","셋 가운데 더 나은 매체는 없어요."]}'::jsonb),
('g6_2_kor_u5_L01_challenge#8','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C1',4,'mc','auto','도아가 「말씀은 지나갔지만 글은 그대로 남아 있으니까.」라고 한 말과 이 단원의 약속을 함께 생각할 때 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X02','K6-2-u5-X03']::text[],false,'{"seq":8,"concept":"K6-2-u5-C1","difficulty":4,"kind":"mc","stem":"도아가 「말씀은 지나갔지만 글은 그대로 남아 있으니까.」라고 한 말과 이 단원의 약속을 함께 생각할 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"이 상황에서는 글이 남아 도움이 되었지만, 녹음한 말처럼 말이 남는 경우도 있으니 매체마다 살펴야 한다","correct":true},{"t":"글은 언제나 남으니 앞으로 모든 안내는 글로만 하면 된다","mis":"K6-2-u5-X02"},{"t":"선생님이 말로 하신 것이 잘못이다","mis":"K6-2-u5-X03"},{"t":"도아의 말은 틀렸다. 글도 금방 사라진다","mis":"K6-2-u5-X02"}],"explanation":["이 상황에서는 글이 남아 다시 볼 수 있었어요.","그렇다고 언제나 그런 것은 아니에요.","매체에 따라 남고 사라지는 것이 달라져요."],"asset":{"type":"speech","turns":[{"who":"시율","text":"도아야, 아까 선생님이 준비물 말씀하셨잖아. 뭐였지?"},{"who":"도아","text":"나도 앞부분만 기억나. 잠깐, 알림 게시글에도 올라와 있어."},{"who":"시율","text":"아, 글로도 올려 주셨구나. 그럼 다시 읽어 보면 되겠다."},{"who":"도아","text":"응. 말씀은 지나갔지만 글은 그대로 남아 있으니까."}]}}'::jsonb),
('g6_2_kor_u5_L01_challenge#9','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C2',4,'essay','teacher','「말은 언제나 사라지고 글은 언제나 남는다.」라는 말이 왜 알맞지 않은지 예를 두 가지 들어 쓰고, 어떻게 알아 두어야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u5-C2","difficulty":4,"kind":"essay","stem":"「말은 언제나 사라지고 글은 언제나 남는다.」라는 말이 왜 알맞지 않은지 예를 두 가지 들어 쓰고, 어떻게 알아 두어야 하는지 쓰세요.","answer_guide":{"answer":"예: 음성 메모로 녹음한 말은 다시 들을 수 있어서 말인데도 남는다. 잠깐 떴다 사라지는 알림이나 넘기면 없어지는 자막은 글인데도 다시 보기 어렵다. 그래서 말은 보통 그 자리에서 사라지고 글은 보통 오래 남는다는 것은 기본 성질일 뿐이고, 매체에 따라 달라지므로 이 매체에서는 어떻게 되는지 그때그때 살펴야 한다.","scoring_points":["말인데 남는 예를 들었는가","글인데 흘러가는 예를 들었는가","기본 성질이며 매체에 따라 달라진다고 썼는가"]},"explanation":["녹음한 말을 떠올려요.","사라지는 알림을 떠올려요.","규칙이 아니라 기본 성질이에요."]}'::jsonb),
('g6_2_kor_u5_L01_challenge#10','kor',6,2,'u5','L01','g6_2_kor_u5_L01_challenge','lesson_challenge','K6-2-u5-C6',4,'essay','teacher','「멀리 이사 간 친구에게 생일 축하하는 마음 전하기」와 「모둠 과제의 차례 다섯 가지 알리기」 가운데 하나를 골라 알맞은 방법(말 · 글 · 둘 다)을 정하고, 그 까닭을 언어의 특성과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u5-C6","difficulty":4,"kind":"essay","stem":"「멀리 이사 간 친구에게 생일 축하하는 마음 전하기」와 「모둠 과제의 차례 다섯 가지 알리기」 가운데 하나를 골라 알맞은 방법(말 · 글 · 둘 다)을 정하고, 그 까닭을 언어의 특성과 이어 쓰세요.","answer_guide":{"answer":"예: 모둠 과제의 차례 다섯 가지를 알릴 때는 글로 적어 두는 것이 알맞다. 차례가 여러 개라 나중에 다시 봐야 하는데, 글은 그대로 남아 필요할 때 다시 볼 수 있고 모둠원이 똑같은 내용을 나누어 가질 수 있기 때문이다. (또는) 생일 축하는 영상 통화로 직접 말로 전하는 것이 알맞다. 목소리의 크기와 억양으로 반가운 마음을 생생하게 전할 수 있기 때문이다.","scoring_points":["상황 하나를 골라 방법을 정했는가","까닭을 썼는가","까닭을 언어의 특성과 이어 썼는가"]},"explanation":["고르는 것까지는 절반이에요.","왜 그런지를 써요.","특성과 이어야 까닭이 돼요."]}'::jsonb),
('g6_2_kor_u5_L02_basic#1','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',1,'mc','auto','안내 글에서 중요한 내용을 눈에 띄게 한 방법은 어느 것인가요?',ARRAY['K6-2-u5-X06']::text[],false,'{"seq":1,"concept":"K6-2-u5-C4","difficulty":1,"kind":"mc","stem":"안내 글에서 중요한 내용을 눈에 띄게 한 방법은 어느 것인가요?","options":[{"t":"글자를 굵게 하고 줄을 나누었다","correct":true},{"t":"목소리를 크게 했다","mis":"K6-2-u5-X06"},{"t":"배경 음악을 넣었다","mis":"K6-2-u5-X06"},{"t":"말을 천천히 했다","mis":"K6-2-u5-X06"}],"explanation":["목소리 · 음악 · 말의 속도는 말로 할 때 쓰는 방법이에요.","글에서는 글자 굵기와 줄 나눔을 써요.","그래서 목장갑과 겉옷이 눈에 띄어요."],"asset":{"type":"passage","lines":["학급 텃밭 가꾸기 안내","언제 · 다음 주 목요일 다섯째 시간","어디에서 · 학교 뒤편 작은 텃밭 / 무엇을 · 상추 모종 심기","챙길 것 · 손을 덮는 【목장갑】을 꼭 가져오세요.","· 흙이 묻어도 되는 【겉옷】을 입고 오세요.","· 모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다."],"title":"학급 게시판에 붙은 안내 글 (【 】는 굵은 글씨)"}}'::jsonb),
('g6_2_kor_u5_L02_basic#2','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',1,'mc','auto','방송하는 사람이 중요한 곳을 알린 방법은 어느 것인가요?',ARRAY['K6-2-u5-X06']::text[],false,'{"seq":2,"concept":"K6-2-u5-C5","difficulty":1,"kind":"mc","stem":"방송하는 사람이 중요한 곳을 알린 방법은 어느 것인가요?","options":[{"t":"목소리를 크고 또박또박하게 하고 말을 천천히 했다","correct":true},{"t":"중요한 낱말에 밑줄을 그었다","mis":"K6-2-u5-X06"},{"t":"문장 끝에 느낌표를 붙였다","mis":"K6-2-u5-X06"},{"t":"글자를 크게 썼다","mis":"K6-2-u5-X06"}],"explanation":["밑줄 · 느낌표 · 글자 크기는 글의 방법이에요.","말에서는 목소리의 크기와 속도를 써요.","괄호 안을 다시 읽어 보세요."],"asset":{"type":"passage","lines":["자, 알림 하나 하겠습니다. 다음 주 목요일 다섯째 시간에","학교 뒤편 텃밭에서 상추 모종을 심습니다.","(목소리를 크고 또박또박하게) 목장갑을 꼭 가져오세요.","흙이 묻어도 되는 겉옷을 입고 오면 됩니다.","(말을 천천히 하며) 모종은 학교에서 준비합니다.","따로 사 오지 않아도 됩니다."],"title":"같은 안내를 방송으로 한 말 (괄호는 목소리가 달라진 곳)"}}'::jsonb),
