('g6_2_kor_u5_L02_basic#6','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C5',2,'mc','auto','음성 언어의 특성으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u5-X01','K6-2-u5-X06']::text[],false,'{"seq":6,"concept":"K6-2-u5-C5","difficulty":2,"kind":"mc","stem":"음성 언어의 특성으로 알맞은 것은 어느 것인가요?","options":[{"t":"듣는 사람의 반응을 보며 다시 설명할 수 있다","correct":true},{"t":"적은 내용이 그대로 남는다","mis":"K6-2-u5-X01"},{"t":"글자의 굵기로 중요한 곳을 보인다","mis":"K6-2-u5-X06"},{"t":"쓴 뒤에 천천히 고칠 수 있다","mis":"K6-2-u5-X01"}],"explanation":["남기 · 굵기 · 고치기는 문자 언어의 특성이에요.","말은 마주 보고 해요.","그래서 반응을 보며 바꿀 수 있어요."]}'::jsonb),
('g6_2_kor_u5_L02_basic#7','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C6',2,'mc','auto','복잡한 차례를 글로도 적어 주면 좋은 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u5-X09']::text[],false,'{"seq":7,"concept":"K6-2-u5-C6","difficulty":2,"kind":"mc","stem":"복잡한 차례를 글로도 적어 주면 좋은 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글로 적으면 언제나 더 훌륭한 안내가 되기 때문에","correct":true},{"t":"잊어버렸을 때 다시 볼 수 있기 때문에","mis":"K6-2-u5-X09"},{"t":"차례를 눈으로 짚어 가며 따라 할 수 있기 때문에","mis":"K6-2-u5-X09"},{"t":"여러 사람이 똑같은 내용을 나누어 갖기 때문에","mis":"K6-2-u5-X09"}],"explanation":["세 까닭은 글의 특성과 이어져 있어요.","「언제나 더 훌륭하다」는 등수를 매긴 말이에요.","까닭은 특성과 이어 말해요."]}'::jsonb),
('g6_2_kor_u5_L02_basic#8','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C7',2,'ox','auto','어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓰면 좋아요.',ARRAY['K6-2-u5-X11']::text[],false,'{"seq":8,"concept":"K6-2-u5-C7","difficulty":2,"kind":"ox","stem":"어렵거나 헷갈리는 내용일수록 말과 글을 함께 쓰면 좋아요.","answer":"O","reason_options":[{"t":"말로 놓친 곳을 글로 다시 확인할 수 있기 때문에","correct":true},{"t":"같은 내용을 두 번 쓰면 시간이 아깝기 때문에","mis":"K6-2-u5-X11"}],"mis":"K6-2-u5-X11","explanation":["말은 생생하지만 놓치면 되돌릴 수 없어요.","글은 남아서 다시 볼 수 있어요.","둘을 함께 쓰면 서로 보완해요."]}'::jsonb),
('g6_2_kor_u5_L02_basic#9','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C4',2,'mc','auto','안내 글과 방송을 견주었을 때 안내 글만 할 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u5-X06','K6-2-u5-X08']::text[],false,'{"seq":9,"concept":"K6-2-u5-C4","difficulty":2,"kind":"mc","stem":"안내 글과 방송을 견주었을 때 안내 글만 할 수 있는 것은 어느 것인가요?","options":[{"t":"집에 가서도 챙길 것을 다시 읽어 볼 수 있다","correct":true},{"t":"목소리로 「꼭」을 힘주어 말할 수 있다","mis":"K6-2-u5-X06"},{"t":"듣는 사람이 그 자리에서 되물을 수 있다","mis":"K6-2-u5-X08"},{"t":"말을 천천히 해서 중요한 곳을 알린다","mis":"K6-2-u5-X06"}],"explanation":["힘주어 말하기와 되묻기, 천천히 말하기는 말의 특성이에요.","글은 남아 있어요.","그래서 나중에 다시 볼 수 있어요."],"asset":{"type":"passage","lines":["학급 텃밭 가꾸기 안내","언제 · 다음 주 목요일 다섯째 시간","어디에서 · 학교 뒤편 작은 텃밭 / 무엇을 · 상추 모종 심기","챙길 것 · 손을 덮는 【목장갑】을 꼭 가져오세요.","· 흙이 묻어도 되는 【겉옷】을 입고 오세요.","· 모종은 학교에서 준비하니 따로 사 오지 않아도 됩니다."],"title":"학급 게시판에 붙은 안내 글 (【 】는 굵은 글씨)"}}'::jsonb),
('g6_2_kor_u5_L02_basic#10','kor',6,2,'u5','L02','g6_2_kor_u5_L02_basic','lesson_basic','K6-2-u5-C6',3,'error','auto','「이 상황에는 문자 언어가 알맞다」를 말했어요. 까닭까지 바르게 말하지 않은 친구는 누구인가요?',ARRAY['K6-2-u5-X09']::text[],false,'{"seq":10,"concept":"K6-2-u5-C6","difficulty":3,"kind":"error","stem":"「이 상황에는 문자 언어가 알맞다」를 말했어요. 까닭까지 바르게 말하지 않은 친구는 누구인가요?","options":[{"t":"민서 — 「글이 알맞아. 그냥 글이 좋으니까.」","correct":true,"mis_target":"K6-2-u5-X09"},{"t":"주원 — 「차례가 여러 개라 나중에 다시 봐야 하는데, 글은 그대로 남거든.」","mis":"K6-2-u5-X09"},{"t":"가은 — 「여러 사람이 똑같은 내용을 정확하게 나누어 가져야 해서야.」","mis":"K6-2-u5-X09"}],"explanation":["주원과 가은은 까닭을 글의 특성과 이었어요.","민서는 고르기만 하고 까닭이 없어요.","고른 까닭까지가 답이에요."]}'::jsonb),
