('g6_2_kor_u6_review_c#15','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C23',2,'ox','auto','지안이의 계획에서 절정의 「하늘에서 로봇이 내려온다」는 앞의 일과 자연스럽게 이어져요.',ARRAY['K6-2-u6-X29']::text[],false,'{"seq":15,"concept":"K6-2-u6-C23","difficulty":2,"kind":"ox","stem":"지안이의 계획에서 절정의 「하늘에서 로봇이 내려온다」는 앞의 일과 자연스럽게 이어져요.","answer":"X","reason_options":[{"t":"앞에서 로봇이 나올 까닭이 없어 갑작스럽기 때문에","correct":true},{"t":"놀라운 일은 언제나 앞의 일과 이어지기 때문에","mis":"K6-2-u6-X29"}],"mis":"K6-2-u6-X29","explanation":["앞의 일에 로봇은 없었어요.","갑자기 나타나면 이어지지 않아요.","앞이 뒤를 불러야 해요."],"asset":{"type":"passage","lines":["원래 이야기 · 여름 내내 노래만 한 베짱이가 겨울에 개미를 찾아간다","바꿀 것 · 베짱이의 성격 — 게으름 → 남을 위해 노래를 연습하는 성격","전개 · 베짱이는 여름 내내 아무것도 하지 않고 낮잠만 잔다","절정 · 겨울에 갑자기 하늘에서 커다란 로봇이 내려와 먹이를 나누어 준다","마지막 · 모두 로봇 덕분에 행복해진다","제목 · 개미와 베짱이"],"title":"지안이의 「개미와 베짱이」 바꾸기 계획"}}'::jsonb),
('g6_2_kor_u6_review_c#16','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C31',2,'ox','auto','시후의 말처럼 누가 읽을지는 책을 다 만든 뒤에 정해도 괜찮아요.',ARRAY['K6-2-u6-X39']::text[],false,'{"seq":16,"concept":"K6-2-u6-C31","difficulty":2,"kind":"ox","stem":"시후의 말처럼 누가 읽을지는 책을 다 만든 뒤에 정해도 괜찮아요.","answer":"X","reason_options":[{"t":"독자가 정해져야 책의 형태와 내용이 따라 정해지기 때문에","correct":true},{"t":"독자는 책의 내용과 상관없기 때문에","mis":"K6-2-u6-X39"}],"mis":"K6-2-u6-X39","explanation":["세윤이도 독자부터 정하자고 했어요.","독자가 형태를 정해요.","먼저 정해요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb),
