('g6_2_kor_u6_review_c#18','kor',6,2,'u6','','g6_2_kor_u6_review_c','unit_review','K6-2-u6-C14',3,'mc','auto','도윤이가 「소풍」의 제목을 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X18']::text[],false,'{"seq":18,"concept":"K6-2-u6-C14","difficulty":3,"kind":"mc","stem":"도윤이가 「소풍」의 제목을 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쪽지 한 장이 내 것이 된 날","correct":true},{"t":"소풍 간 날 있었던 모든 일","mis":"K6-2-u6-X18"},{"t":"공원","mis":"K6-2-u6-X18"},{"t":"버스","mis":"K6-2-u6-X18"}],"explanation":["겪은 일 그대로의 제목은 마음이 흐려요.","버스와 공원은 인상 깊은 순간이 아니에요.","쪽지를 찾은 기쁨이 담기면 좋아요."],"asset":{"type":"passage","lines":["아침에 일어나 세수를 하고 김밥을 쌌다 버스를 탔다","버스에서 노래를 불렀다 공원에 도착했다 날씨가 맑았다","보물찾기를 했는데 내가 쪽지를 찾았다 너무 좋았다","김밥을 먹고 사진을 찍고 버스를 타고 집에 왔다 재미있었다"],"title":"도윤이가 처음 쓴 시 「소풍」 (연을 나누지 않고 이어 씀)"}}'::jsonb),
