('g6_2_kor_u6_review_d#22','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C26',3,'mc','auto','「토끼와 자라」를 자라 바꾸기 계획대로 바꾸면 새로 생길 수 있는 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X32']::text[],false,'{"seq":22,"concept":"K6-2-u6-C26","difficulty":3,"kind":"mc","stem":"「토끼와 자라」를 자라 바꾸기 계획대로 바꾸면 새로 생길 수 있는 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"속이지 않고 사정을 털어놓으면 함께 길을 찾을 수 있다","correct":true},{"t":"꾀가 많은 사람이 언제나 이긴다","mis":"K6-2-u6-X32"},{"t":"용왕의 말은 무조건 따라야 한다","mis":"K6-2-u6-X32"},{"t":"바닷속은 위험한 곳이다","mis":"K6-2-u6-X32"}],"explanation":["원래는 토끼가 꾀로 살아남는 이야기예요.","바꾸자 자라가 사실대로 말하고 함께 약을 찾아요.","정직하게 털어놓는 뜻이 새로 생겨요."],"asset":{"type":"passage","lines":["바꿀 것 · 자라의 성격","   맡은 일을 끝까지 해내려는 성격 → 스스로 따져 보는 성격","전개 · 데려가는 길에 자라가 토끼에게 사정을 사실대로 말한다","절정 · 토끼는 달아나는 대신 함께 다른 약을 찾아보자고 한다","마지막 · 둘이 용궁의 서고를 뒤져 바닷속 약초를 찾아낸다","그대로 두는 것 · 배경(바닷속 용궁과 산), 용왕의 성격"],"title":"「토끼와 자라」 바꾸기 계획"}}'::jsonb),
('g6_2_kor_u6_review_d#23','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C33',4,'mc','auto','학급 이야기책 회의를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u6-X41','K6-2-u6-X38','K6-2-u6-X39']::text[],false,'{"seq":23,"concept":"K6-2-u6-C33","difficulty":4,"kind":"mc","stem":"학급 이야기책 회의를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나래의 말처럼 중심 사건과 인물부터 정하고, 독자를 먼저 정해 형태를 고르며, 꾸미기는 이야기 뒤에, 나눌 때는 잘한 점부터 해야 한다","correct":true},{"t":"다온의 말처럼 표지를 먼저 꾸미면 된다","mis":"K6-2-u6-X41"},{"t":"루아의 말처럼 화면으로 보는 책이 언제나 정답이다","mis":"K6-2-u6-X38"},{"t":"시후의 말처럼 독자는 나중에 정해도 된다","mis":"K6-2-u6-X39"}],"explanation":["나래의 말이 알맞아요.","독자부터 정해요.","이야기가 먼저, 잘한 점부터 나눠요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb),
('g6_2_kor_u6_review_d#24','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C31',4,'essay','teacher','학급 이야기책 회의에서 알맞지 않은 말을 세 가지 골라 왜 알맞지 않은지 쓰고, 우리 반 책을 만드는 차례를 바르게 다시 정리하세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u6-C31","difficulty":4,"kind":"essay","stem":"학급 이야기책 회의에서 알맞지 않은 말을 세 가지 골라 왜 알맞지 않은지 쓰고, 우리 반 책을 만드는 차례를 바르게 다시 정리하세요.","answer_guide":{"answer":"예: 첫째, 다온이가 표지부터 사흘 동안 꾸미자고 했는데, 꾸미기가 이야기를 덮으면 안 되므로 이야기를 먼저 완성해야 한다. 둘째, 루아가 화면으로 보는 책이 제일 좋다고 했는데, 형태에는 등수가 없고 독자에 따라 달라진다. 셋째, 시후가 독자를 나중에 정하자고 했는데, 독자가 정해져야 형태가 정해진다. 바른 차례 — 독자 정하기 → 독자에게 맞는 형태 고르기 → 중심 사건 · 인물 · 때와 곳 · 차례 정하고 글 쓰기 → 누가 무엇을 언제까지 맡을지 나누어 만들기 → 꾸미기는 돕는 만큼 → 다 만든 뒤 잘한 점부터 나누기.","scoring_points":["알맞지 않은 말 세 가지와 까닭을 썼는가","독자를 먼저 정하고 형태를 고르는 차례를 썼는가","이야기 먼저 · 꾸미기는 돕는 만큼 · 잘한 점부터를 썼는가"]},"explanation":["독자부터 정해요.","이야기가 먼저예요.","잘한 점부터 나눠요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"우리 책은 표지가 제일 중요해. 표지부터 사흘 동안 꾸미자."},{"who":"루아","text":"화면으로 보는 책이 제일 좋은 형태니까 무조건 그걸로 하자."},{"who":"시후","text":"누가 읽을지는 나중에 정해도 돼. 일단 만들자."},{"who":"나래","text":"중심 사건이랑 인물 성격부터 정해 두면 글이 빨리 써질 거야."},{"who":"하람","text":"다 만들면 서로 고칠 점부터 말해 주자."}]}}'::jsonb),
('g6_2_kor_u6_review_d#25','kor',6,2,'u6','','g6_2_kor_u6_review_d','unit_review','K6-2-u6-C34',4,'essay','teacher','「메다 · 매다」를 모두 넣어 오늘 겪은 일을 짧은 글로 쓰고, 두 낱말을 어떻게 가려 썼는지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u6-C34","difficulty":4,"kind":"essay","stem":"「메다 · 매다」를 모두 넣어 오늘 겪은 일을 짧은 글로 쓰고, 두 낱말을 어떻게 가려 썼는지 설명하세요.","answer_guide":{"answer":"예: 아침에 운동화 끈을 단단히 매고, 무거운 가방을 어깨에 메고 학교까지 뛰어갔다. 「매다」는 끈이나 줄을 묶을 때 쓰므로 운동화 끈 자리에 썼고, 「메다」는 어깨에 걸쳐 질 때 쓰므로 가방 자리에 썼다. 두 낱말은 소리가 같지만 뜻이 달라 앞뒤 문장을 보고 골라 써야 한다.","scoring_points":["두 낱말을 모두 넣어 겪은 일을 썼는가","각 낱말을 뜻에 맞는 자리에 썼는가","가려 쓴 까닭을 뜻으로 설명했는가"]},"explanation":["겪은 일 가운데 떠올려요.","뜻에 맞는 자리에 써요.","앞뒤 문장을 보고 골라요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('M6-2-u1-C1','math',6,2,'u1',2,'나누는 수가 분수인 나눗셈의 뜻 — 같은 종류의 양을 얼마씩 몇 번 덜어 낼 수 있는지 묻는 자리임을 알고, (자연수)÷(자연수)·(분수)÷(자연수)를 바탕으로 식을 세우기',ARRAY['6수01-10']::text[],1),
('M6-2-u1-C2','math',6,2,'u1',2,'분모가 같은 (분수)÷(분수) — 두 분수가 같은 단위분수 몇 개인지 세어 분자끼리 나누고, 분모는 답에 남지 않음을 알기',ARRAY['6수01-10']::text[],2),
('M6-2-u1-C3','math',6,2,'u1',3,'분모가 같은 (분수)÷(분수) — 분자끼리 나누어떨어지지 않으면 몫을 분수로 나타내고, 몫의 분수 부분은 남은 양이 아니라 한 몫의 얼마인지를 뜻함을 알기',ARRAY['6수01-10']::text[],3),
('M6-2-u1-C4','math',6,2,'u1',4,'분모가 다른 (분수)÷(분수) — 두 분수를 같은 크기의 조각으로 다시 세는 통분을 한 뒤 분자끼리 나누기',ARRAY['6수01-10']::text[],4),
('M6-2-u1-C5','math',6,2,'u1',5,'(자연수)÷(단위분수) — 단위분수가 1 안에 분모만큼 들어감을 알고 자연수에 분모를 곱해 구하며, 1보다 작은 수로 나누면 몫이 나누어지는 수보다 커짐을 알기',ARRAY['6수01-10']::text[],5),
('M6-2-u1-C6','math',6,2,'u1',6,'(자연수)÷(진분수) — 분자로 나누고 분모를 곱하는 두 걸음을 한 줄로 적어 나누는 분수의 분모와 분자를 바꾸어 곱하기',ARRAY['6수01-10']::text[],6),
('M6-2-u1-C7','math',6,2,'u1',7,'(분수)÷(분수)를 분수의 곱셈으로 — 나누는 분수만 분모와 분자를 바꾸어 곱하고, 나누어지는 분수는 그대로 두어야 함을 알기',ARRAY['6수01-10']::text[],7),
('M6-2-u1-C8','math',6,2,'u1',8,'대분수의 나눗셈 — 대분수를 먼저 가분수로 고친 뒤 통분해 분자끼리 나누거나 곱셈으로 바꾸어 계산하기(두 길의 답은 같다)',ARRAY['6수01-10']::text[],8),
('M6-2-u1-C9','math',6,2,'u1',9,'문제 해결 — 길이 ÷ 타일 한 변으로 가로·세로에 들어가는 개수를 구하고, 가로 수 × 세로 수로 필요한 타일 수를 구하기(조건을 바꾸어도 방법은 같다)',ARRAY['6수01-10']::text[],9)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('M6-2-u1-X01','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C6','M6-2-u1-C7']::text[],'나눗셈식을 거꾸로 세운다 — 나누어지는 양과 나누는 양을 바꾸어 (나누는 양)÷(나누어지는 양)으로 쓴다','「무엇을 얼마씩」 — 무엇이 앞, 얼마씩이 뒤'),
('M6-2-u1-X02','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C3']::text[],'분모가 같은 나눗셈에서 분모를 답에 남기거나 분모끼리도 나눈다(⟨3/4⟩ ÷ ⟨1/4⟩ = ⟨3/4⟩, 분모끼리 4 ÷ 4)','같은 조각이면 개수만 — 분모는 답에 안 남아요'),
('M6-2-u1-X03','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C3','M6-2-u1-C5','M6-2-u1-C6']::text[],'나눗셈 대신 분자끼리 빼거나 더한다(연산을 바꾼다)','「몇 번 덜어 낼 수 있나」는 나눗셈'),
('M6-2-u1-X04','math',6,'u1',ARRAY['M6-2-u1-C3']::text[],'몫의 분수 부분을 「남은 양」으로 읽는다(⟨5/6⟩ ÷ ⟨2/6⟩ = 2⟨1/2⟩에서 ⟨1/2⟩이 남았다고 본다)','몫은 컵의 수 — 분수 부분은 컵 하나의 얼마'),
('M6-2-u1-X05','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C7','M6-2-u1-C8']::text[],'나누어떨어지지 않을 때 몫을 거꾸로 적는다(4 ÷ 7을 ⟨7/4⟩로)','나누어지는 수가 분자, 나누는 수가 분모'),
('M6-2-u1-X06','math',6,'u1',ARRAY['M6-2-u1-C4']::text[],'분모가 다른데 통분하지 않고 분자끼리 바로 나눈다','조각 크기가 다르면 먼저 같은 조각으로'),
('M6-2-u1-X07','math',6,'u1',ARRAY['M6-2-u1-C4']::text[],'통분을 한쪽만 하거나 분모만 바꾸고 분자를 그대로 둔다','분모를 바꾼 만큼 분자도 같이'),
('M6-2-u1-X08','math',6,'u1',ARRAY['M6-2-u1-C5']::text[],'(자연수)÷(단위분수)에서 분모로 나누거나 분모만 답으로 쓴다(5 ÷ ⟨1/3⟩ = ⟨5/3⟩)','⟨1/3⟩은 1 안에 3번 — 분모를 곱해요'),
('M6-2-u1-X09','math',6,'u1',ARRAY['M6-2-u1-C5','M6-2-u1-C6']::text[],'「나눗셈을 하면 몫은 늘 작아진다」고 여겨 몫이 커지는 것을 틀렸다고 본다','1보다 작은 수로 나누면 몫이 커져요'),
('M6-2-u1-X10','math',6,'u1',ARRAY['M6-2-u1-C6','M6-2-u1-C7','M6-2-u1-C9']::text[],'나누는 분수를 뒤집지 않고 그대로 곱한다(4 ÷ ⟨2/3⟩ = 4 × ⟨2/3⟩)','나누는 분수의 분모와 분자를 바꾸어 곱해요'),
('M6-2-u1-X11','math',6,'u1',ARRAY['M6-2-u1-C6','M6-2-u1-C9']::text[],'두 걸음의 순서를 거꾸로 한다 — 분모로 나누고 분자를 곱한다','분자로 나누고(÷2) 분모를 곱해요(×3)'),
('M6-2-u1-X12','math',6,'u1',ARRAY['M6-2-u1-C7','M6-2-u1-C8']::text[],'두 분수를 다 뒤집거나 앞 분수를 뒤집는다(또는 아무것도 안 뒤집고 곱한다)','뒤집는 것은 나누는 분수 하나뿐'),
('M6-2-u1-X13','math',6,'u1',ARRAY['M6-2-u1-C8','M6-2-u1-C9']::text[],'대분수를 가분수로 고치지 않고 자연수 부분과 분수 부분을 따로 나누거나 대분수 그대로 뒤집는다','대분수는 먼저 가분수로'),
('M6-2-u1-X14','math',6,'u1',ARRAY['M6-2-u1-C8']::text[],'대분수를 가분수로 잘못 고친다(자연수와 분자를 더하거나 분모를 곱하지 않는다)','자연수 × 분모 + 분자가 분자'),
('M6-2-u1-X15','math',6,'u1',ARRAY['M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C7','M6-2-u1-C8']::text[],'계산 마무리 실수 — 약분하지 않거나 가분수·대분수로 잘못 고친다','몫은 약분해서 대분수로'),
('M6-2-u1-X16','math',6,'u1',ARRAY['M6-2-u1-C2','M6-2-u1-C4','M6-2-u1-C5','M6-2-u1-C6','M6-2-u1-C7']::text[],'몫을 견줄 때 나누는 수가 클수록 몫도 크다고 여긴다','나누는 수가 작을수록 몫이 커요'),
('M6-2-u1-X17','math',6,'u1',ARRAY['M6-2-u1-C9']::text[],'가로에 들어가는 수와 세로에 들어가는 수를 더해 전체 타일 수로 본다(곱해야 한다)','가로 줄이 세로 줄 수만큼 늘어선 것 — 곱하기'),
('M6-2-u1-X18','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C2','M6-2-u1-C5','M6-2-u1-C9']::text[],'무엇을 묻는지 놓친다 — 개수를 묻는데 양을 쓰거나 나누어지는 양을 그대로 답으로 쓴다','묻는 것이 「몇 개」인지 「얼마」인지 확인'),
('M6-2-u1-X19','math',6,'u1',ARRAY['M6-2-u1-C8']::text[],'어떤 수 문제에서 거꾸로 계산을 잘못한다 — 곱한 결과를 다시 곱하거나 결과를 그대로 어떤 수로 본다','곱했으면 거꾸로 나누어 어떤 수를 찾기'),
('M6-2-u1-X20','math',6,'u1',ARRAY['M6-2-u1-C1','M6-2-u1-C2','M6-2-u1-C3','M6-2-u1-C4','M6-2-u1-C5','M6-2-u1-C6','M6-2-u1-C7','M6-2-u1-C8','M6-2-u1-C9']::text[],'묻는 말을 거꾸로 읽는다 — 옳은↔잘못된, 큰↔작은, 가능↔불가능','물음의 「잘못·가장·없는」에 동그라미 치기')
